//! semantics that `jscodeshift`'s ignore rules rely on.
//!
//! `picomatch` compiles a glob to a JavaScript regular expression; this module compiles the same
//! glob to an equivalent [`regex`] pattern so `ignoreFiles` keeps matching identically. Only the
//! `{ dot: true }` configuration used by `ignoreFiles` is modelled.

use regex::Regex;

/// A compiled glob pattern.
#[derive(Debug)]
pub struct Glob {
    regex: Regex,
    negated: bool,
}

impl Glob {
    pub fn new(pattern: &str) -> Option<Self> {
        let (negated, body) = split_negation(pattern);
        let source = compile(body)?;
        let regex = Regex::new(&source).ok()?;
        Some(Glob { regex, negated })
    }

    pub fn is_match(&self, path: &str) -> bool {
        // picomatch matches windows separators against `/` in the pattern.
        let normalized = path.replace('\\', "/");
        self.regex.is_match(&normalized) != self.negated
    }
}

/// `!` prefixes negate a pattern; a literal leading `!` is escaped as `\!`.
fn split_negation(pattern: &str) -> (bool, &str) {
    let mut rest = pattern;
    let mut negated = false;
    while let Some(stripped) = rest.strip_prefix('!') {
        if stripped.starts_with('(') {
            // `!(...)` is an extglob, not a negation.
            break;
        }
        negated = !negated;
        rest = stripped;
    }
    (negated, rest)
}

/// Matches any path segment sequence that contains no `.`/`..` segment.
///
/// picomatch's `dot: true` still refuses to let `**` match across a relative traversal segment,
/// which is the behavior `ignoreFiles` compensates for by stripping leading `./`/`../`.
const NO_DOT_SEGMENT: &str = r"(?:(?:(?:^|/)\.{1,2}(?:/|$))?+.)*?";
const NOT_DOT_SEGMENT_AHEAD: &str = r"(?:(?!(?:^|/)\.{1,2}(?:/|$)).)*?";
const NOT_RELATIVE_AHEAD: &str = r"(?!\.{1,2}(?:/|$))";

struct Compiler<'a> {
    chars: Vec<char>,
    pos: usize,
    out: String,
    /// Whether the pattern used any glob metacharacter. Purely literal patterns are anchored
    /// exactly (picomatch emits `^(?:^(?:literal)$)$` for them).
    has_magic: bool,
    pattern: &'a str,
}

/// Compiles `pattern` into a regex source string equivalent to `picomatch.makeRe(pattern, {dot: true})`.
fn compile(pattern: &str) -> Option<String> {
    let mut compiler = Compiler {
        chars: pattern.chars().collect(),
        pos: 0,
        out: String::new(),
        has_magic: false,
        pattern,
    };
    compiler.compile_sequence(None)?;
    if compiler.pos != compiler.chars.len() {
        return None;
    }
    let body = compiler.out;
    if compiler.has_magic {
        Some(format!("^(?:{body})$"))
    } else {
        Some(format!("^(?:^(?:{body})$)$"))
    }
}

impl Compiler<'_> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn at_segment_start(&self) -> bool {
        self.pos == 0 || self.chars.get(self.pos - 1) == Some(&'/')
    }

    /// Compiles until end of input, or until `stop` is found at the top level.
    fn compile_sequence(&mut self, stop: Option<&[char]>) -> Option<()> {
        while let Some(c) = self.peek() {
            if let Some(stop) = stop {
                if stop.contains(&c) {
                    return Some(());
                }
            }
            match c {
                '*' => self.compile_star()?,
                '?' if self.is_extglob() => self.compile_extglob("(?=.)(?:", ")?")?,
                '+' if self.is_extglob() => self.compile_extglob("(?=.)(?:", ")+")?,
                '@' if self.is_extglob() => self.compile_extglob("(", ")")?,
                '!' if self.is_extglob() => self.compile_negated_extglob()?,
                '?' => {
                    self.has_magic = true;
                    self.out.push_str("[^/]");
                    self.pos += 1;
                }
                '[' => self.compile_bracket(),
                '{' => self.compile_brace()?,
                '\\' => {
                    self.pos += 1;
                    match self.peek() {
                        Some(next) => {
                            self.out.push_str(&regex::escape(&next.to_string()));
                            self.pos += 1;
                        }
                        None => self.out.push_str(r"\\"),
                    }
                }
                _ => {
                    self.out.push_str(&regex::escape(&c.to_string()));
                    self.pos += 1;
                }
            }
        }
        Some(())
    }

    fn is_extglob(&self) -> bool {
        self.peek_at(1) == Some('(')
    }

    /// `?(a|b)`, `+(a|b)`, `@(a|b)`: the body is a `|`-separated list of globs.
    fn compile_extglob(&mut self, prefix: &str, suffix: &str) -> Option<()> {
        self.has_magic = true;
        self.pos += 2;
        self.out.push_str(prefix);
        self.compile_alternatives()?;
        self.out.push_str(suffix);
        Some(())
    }

    /// `!(a|b)` matches any segment that is not one of the alternatives.
    fn compile_negated_extglob(&mut self) -> Option<()> {
        self.has_magic = true;
        self.pos += 2;
        let mut alternatives = String::new();
        std::mem::swap(&mut self.out, &mut alternatives);
        self.compile_alternatives()?;
        std::mem::swap(&mut self.out, &mut alternatives);
        self.out
            .push_str(&format!("(?:(?!(?:{alternatives})$)[^/]*?)"));
        Some(())
    }

    fn compile_alternatives(&mut self) -> Option<()> {
        loop {
            self.compile_sequence(Some(&['|', ')']))?;
            match self.peek() {
                Some('|') => {
                    self.out.push('|');
                    self.pos += 1;
                }
                Some(')') => {
                    self.pos += 1;
                    return Some(());
                }
                _ => return None,
            }
        }
    }

    /// `{a,b}` brace expansion, compiled as a regex alternation.
    fn compile_brace(&mut self) -> Option<()> {
        // Braces without a comma or range are literal in picomatch.
        let Some(close) = self.find_brace_close() else {
            self.out.push_str(r"\{");
            self.pos += 1;
            return Some(());
        };
        let body: String = self.chars[self.pos + 1..close].iter().collect();
        if !body.contains(',') {
            if let Some(expanded) = expand_numeric_range(&body) {
                self.has_magic = true;
                self.out.push_str(&format!("({expanded})"));
                self.pos = close + 1;
                return Some(());
            }
            self.out.push_str(r"\{");
            self.pos += 1;
            return Some(());
        }
        self.has_magic = true;
        self.pos += 1;
        self.out.push('(');
        loop {
            self.compile_sequence(Some(&[',', '}']))?;
            match self.peek() {
                Some(',') => {
                    self.out.push('|');
                    self.pos += 1;
                }
                Some('}') => {
                    self.pos += 1;
                    self.out.push(')');
                    return Some(());
                }
                _ => return None,
            }
        }
    }

    fn find_brace_close(&self) -> Option<usize> {
        let mut depth = 0usize;
        let mut i = self.pos;
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => i += 1,
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(i);
                    }
                }
                _ => {}
            }
            i += 1;
        }
        None
    }

    /// Character classes. picomatch keeps an unterminated `[` literal, and additionally matches
    /// the literal bracket text itself (e.g. `[abc]` also matches the string `"[abc]"`).
    fn compile_bracket(&mut self) {
        let Some(close) = self.find_bracket_close() else {
            self.out.push_str(r"\[");
            self.pos += 1;
            return;
        };
        self.has_magic = true;
        let raw: String = self.chars[self.pos..=close].iter().collect();
        let inner: String = self.chars[self.pos + 1..close].iter().collect();
        let mut class_body = String::new();
        let mut rest = inner.as_str();
        if let Some(stripped) = rest.strip_prefix('!') {
            class_body.push('^');
            rest = stripped;
        } else if let Some(stripped) = rest.strip_prefix('^') {
            class_body.push('^');
            rest = stripped;
        }
        class_body.push_str(&translate_posix_classes(rest));
        self.out.push_str(&format!(
            "(?:{}|[{}])",
            regex::escape(&raw),
            class_body.replace("[:", "[:")
        ));
        self.pos = close + 1;
    }

    fn find_bracket_close(&self) -> Option<usize> {
        let mut i = self.pos + 1;
        // A `]` in the first position is literal.
        if self.chars.get(i) == Some(&'!') || self.chars.get(i) == Some(&'^') {
            i += 1;
        }
        if self.chars.get(i) == Some(&']') {
            i += 1;
        }
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => i += 1,
                '[' if self.chars.get(i + 1) == Some(&':') => {
                    // POSIX class: skip to `:]`.
                    while i < self.chars.len() && self.chars[i] != ']' {
                        i += 1;
                    }
                }
                ']' => return Some(i),
                _ => {}
            }
            i += 1;
        }
        None
    }

    /// `*` (single segment) and `**` (globstar).
    fn compile_star(&mut self) -> Option<()> {
        let stars = self.count_stars();
        let globstar = stars >= 2;
        self.pos += stars;

        if !globstar {
            self.has_magic = true;
            // A `*` that is not the whole segment does not need the `(?=.)` guard when it follows
            // other magic within the same segment; picomatch emits it for a leading `*`.
            if self.at_star_segment_start() {
                self.out.push_str(NOT_RELATIVE_AHEAD);
                self.out.push_str("(?=.)");
            }
            self.out.push_str("[^/]*?");
            return Some(());
        }

        // picomatch only treats `**` as a globstar when it spans a whole path segment.
        if !self.globstar_is_whole_segment() {
            self.has_magic = true;
            self.out.push_str("[^/]*?");
            return Some(());
        }

        self.has_magic = true;
        let leading_slash = self.out.ends_with('/');
        let trailing_slash = self.peek() == Some('/');

        if leading_slash && trailing_slash {
            // `a/**/b` — the globstar may also collapse to nothing.
            self.out.truncate(self.out.len() - 1);
            self.out
                .push_str(&format!("(?:/{NOT_RELATIVE_AHEAD}({NOT_DOT_SEGMENT_AHEAD})/|/|$)"));
            self.pos += 1;
            return Some(());
        }
        if trailing_slash {
            // Leading `**/` — matches the start of the path or any directory prefix.
            self.out
                .push_str(&format!("(?:^|/|({NOT_DOT_SEGMENT_AHEAD})/)"));
            self.pos += 1;
            return Some(());
        }
        if leading_slash && self.pos == self.chars.len() {
            // Trailing `/**` — matches the directory itself and everything below it.
            self.out.truncate(self.out.len() - 1);
            self.out
                .push_str(&format!("(?:/{NOT_RELATIVE_AHEAD}({NOT_DOT_SEGMENT_AHEAD})|$)"));
            return Some(());
        }
        if self.pos == self.chars.len() && self.out.is_empty() {
            // The whole pattern is `**`.
            self.out.push_str(&format!(
                "(?!(?:^|/)\\.{{1,2}}(?:/|$))({NOT_DOT_SEGMENT_AHEAD})/?"
            ));
            return Some(());
        }
        self.out.push_str(NO_DOT_SEGMENT);
        Some(())
    }

    fn count_stars(&self) -> usize {
        let mut n = 0;
        while self.peek_at(n) == Some('*') {
            n += 1;
        }
        n
    }

    fn at_star_segment_start(&self) -> bool {
        // `self.pos` already points past the consumed star(s).
        let before = self.pos.saturating_sub(1);
        before == 0 || self.chars.get(before - 1) == Some(&'/')
    }

    fn globstar_is_whole_segment(&self) -> bool {
        let stars = {
            let mut n = 0;
            while self.pos >= n + 1 && self.chars.get(self.pos - n - 1) == Some(&'*') {
                n += 1;
            }
            n
        };
        let start = self.pos - stars;
        let starts_segment = start == 0 || self.chars.get(start - 1) == Some(&'/');
        let ends_segment = self.pos == self.chars.len() || self.peek() == Some('/');
        let _ = self.pattern;
        starts_segment && ends_segment
    }
}

fn translate_posix_classes(input: &str) -> String {
    const CLASSES: &[(&str, &str)] = &[
        ("[:alnum:]", "a-zA-Z0-9"),
        ("[:alpha:]", "a-zA-Z"),
        ("[:ascii:]", "\\x00-\\x7F"),
        ("[:blank:]", " \\t"),
        ("[:cntrl:]", "\\x00-\\x1F\\x7F"),
        ("[:digit:]", "0-9"),
        ("[:graph:]", "\\x21-\\x7E"),
        ("[:lower:]", "a-z"),
        ("[:print:]", "\\x20-\\x7E"),
        ("[:punct:]", "\\-!\"#$%&'()*+,./:;<=>?@\\[\\]^_`{|}~"),
        ("[:space:]", " \\t\\r\\n\\v\\f"),
        ("[:upper:]", "A-Z"),
        ("[:word:]", "A-Za-z0-9_"),
        ("[:xdigit:]", "A-Fa-f0-9"),
    ];
    let mut result = input.to_string();
    for (name, replacement) in CLASSES {
        result = result.replace(name, replacement);
    }
    result
}

/// `{1..5}` / `{a..e}` style ranges, which picomatch expands to an alternation.
fn expand_numeric_range(body: &str) -> Option<String> {
    let (start, end) = body.split_once("..")?;
    if let (Ok(start), Ok(end)) = (start.parse::<i64>(), end.parse::<i64>()) {
        if (end - start).abs() > 10_000 {
            return None;
        }
        let values: Vec<String> = if start <= end {
            (start..=end).map(|v| v.to_string()).collect()
        } else {
            (end..=start).rev().map(|v| v.to_string()).collect()
        };
        return Some(values.join("|"));
    }
    let start_chars: Vec<char> = start.chars().collect();
    let end_chars: Vec<char> = end.chars().collect();
    if start_chars.len() == 1 && end_chars.len() == 1 {
        let (a, b) = (start_chars[0] as u32, end_chars[0] as u32);
        let values: Vec<String> = if a <= b {
            (a..=b).filter_map(char::from_u32).map(String::from).collect()
        } else {
            (b..=a)
                .rev()
                .filter_map(char::from_u32)
                .map(String::from)
                .collect()
        };
        return Some(values.join("|"));
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn matches(pattern: &str, path: &str) -> bool {
        Glob::new(pattern)
            .unwrap_or_else(|| panic!("failed to compile {pattern:?}"))
            .is_match(path)
    }

    #[test]
    fn globstar_matches_nested_directories() {
        assert!(matches("**/node_modules/**", "src/node_modules/foo.js"));
        assert!(matches("**/node_modules/**", "/abs/src/node_modules/foo.js"));
        assert!(matches("**/node_modules/**", "src/node_modules"));
        assert!(!matches("**/node_modules/**", "../src/app.js"));
    }

    #[test]
    fn globstar_does_not_cross_traversal_prefix() {
        // Matches picomatch: a leading `../` blocks `**`.
        assert!(!matches(
            "**/node_modules/**",
            "../company.reactapp/src/node_modules/foo.js"
        ));
        assert!(!matches("**/node_modules/**", "./src/node_modules/foo.js"));
    }

    #[test]
    fn bare_name_is_anchored() {
        assert!(matches("node_modules", "node_modules"));
        assert!(!matches("node_modules", "src/node_modules"));
    }

    #[test]
    fn single_star_is_segment_scoped() {
        assert!(matches("*-test.js", "a-test.js"));
        assert!(!matches("*-test.js", "x/a-test.js"));
        assert!(matches("**/*-test.js", "/tmp/x/a-test.js"));
    }

    #[test]
    fn directory_patterns() {
        assert!(matches("sub/dir/", "sub/dir/"));
        assert!(matches("sub/dir/**", "sub/dir"));
        assert!(matches("sub/dir/**", "sub/dir/file.js"));
        assert!(matches("**/sub/dir/**", "/tmp/x/sub/dir/file.js"));
    }

    #[test]
    fn collapsing_globstar() {
        assert!(matches("a/**/b", "a/b"));
        assert!(matches("a/**/b", "a/x/b"));
        assert!(matches("a/**/b", "a/x/y/b"));
        assert!(matches("foo/**/*.js", "foo/bar/baz.js"));
    }

    #[test]
    fn brace_expansion() {
        assert!(matches("**/*.{js,ts}", "foo/bar/baz.ts"));
        assert!(!matches("**/*.{js,ts}", "foo/bar/baz.md"));
    }

    #[test]
    fn negation() {
        assert!(matches("!foo.js", "bar.js"));
        assert!(!matches("!foo.js", "foo.js"));
    }

    #[test]
    fn dot_files_match_with_dot_option() {
        assert!(matches(".*", ".babelrc"));
        assert!(matches("**/.git/**", ".git/config"));
        assert!(matches("**/*.{js,ts}", "x/.hidden/y.js"));
    }

    #[test]
    fn bare_double_star() {
        assert!(matches("**", "foo/bar/baz.js"));
        assert!(matches("**", ".babelrc"));
    }

    #[test]
    fn question_mark_and_classes() {
        assert!(matches("a?c", "abc"));
        assert!(!matches("a?c", "a/c"));
        assert!(matches("[abc]*.js", "a-test.js"));
        assert!(!matches("[abc]*.js", "d-test.js"));
    }

    #[test]
    fn extglobs() {
        assert!(matches("+(a|b).js", "a.js"));
        assert!(matches("@(x)", "x"));
        assert!(matches("?(y)", "y"));
        assert!(matches("?(y)", ""));
        assert!(matches("*(z)", "zzz"));
    }

    #[test]
    fn adjacent_stars_inside_segment_are_not_globstar() {
        assert!(matches("a**b", "axxb"));
        assert!(!matches("a**b", "a/x/b"));
    }

    #[test]
    fn backslash_paths_are_normalized() {
        assert!(matches("**/node_modules/**", "src\\node_modules\\foo.js"));
    }
}
