//! `jscodeshift`'s ignore rules rely on.
//!
//! `picomatch` compiles a glob into a JavaScript regular expression that leans on lookahead
//! assertions. Rather than reproducing those assertions, this module matches path segment by path
//! segment, which expresses the same rules directly:
//!
//! * `**` spans any number of path segments but never crosses a `.` or `..` segment, which is why
//!   `**/node_modules/**` does not match `../src/node_modules/foo.js` upstream either.
//! * Every other wildcard is confined to a single segment.
//! * Only the `{ dot: true }` configuration used by `ignoreFiles` is modelled, so leading dots in
//!   a segment are matched by wildcards, but `.` and `..` segments themselves are not.
//!
//! Parity with the real `picomatch` is pinned by `tests/glob_parity.rs`, which replays a corpus of
//! pattern/path pairs captured from the upstream JavaScript implementation.

/// A compiled glob pattern.
#[derive(Debug, Clone)]
pub struct Glob {
    segments: Vec<Segment>,
    negated: bool,
    /// picomatch appends an optional `/` when a pattern ends in a wildcard, so `*` also matches
    /// `foo/`.
    allow_trailing_slash: bool,
}

#[derive(Debug, Clone)]
enum Segment {
    /// `**` — spans zero or more path segments.
    GlobStar,
    /// Any other segment, matched against exactly one path segment.
    Single {
        nodes: Vec<Node>,
        /// True when the segment starts with a wildcard; picomatch guards those with `(?=.)`,
        /// which forbids matching an empty segment.
        requires_nonempty: bool,
        /// The segment text when it contains no wildcard at all.
        literal: Option<String>,
    },
}

#[derive(Debug, Clone)]
enum Node {
    Literal(String),
    /// `?`
    AnyChar,
    /// `*`
    Star,
    /// `[...]`
    Class {
        /// picomatch also matches the raw bracket text itself, e.g. `[abc]` matches `"[abc]"`.
        raw: String,
        negated: bool,
        items: Vec<ClassItem>,
    },
    /// `{a,b}` and `@(a|b)`
    Alternation(Vec<Vec<Node>>),
    /// `?(a|b)`, `*(a|b)`, `+(a|b)`
    Repeat {
        alternatives: Vec<Vec<Node>>,
        min: usize,
        max: Option<usize>,
    },
    /// `!(a|b)`
    Negated(Vec<Vec<Node>>),
}

#[derive(Debug, Clone)]
enum ClassItem {
    Char(char),
    Range(char, char),
}

impl Glob {
    pub fn new(pattern: &str) -> Option<Self> {
        let (negated, body) = split_negation(pattern);
        let allow_trailing_slash = body.ends_with('*');
        let mut segments = Vec::new();
        for raw in body.split('/') {
            segments.push(compile_segment(raw)?);
        }
        Some(Glob {
            segments,
            negated,
            allow_trailing_slash,
        })
    }

    pub fn is_match(&self, path: &str) -> bool {
        self.matches_path(path) != self.negated
    }

    fn matches_path(&self, path: &str) -> bool {
        // picomatch matches windows separators against `/` in the pattern.
        let normalized = path.replace('\\', "/");
        let path_segments: Vec<&str> = normalized.split('/').collect();
        if match_segments(&self.segments, &path_segments) {
            return true;
        }
        if self.allow_trailing_slash && path_segments.len() > 1 && path_segments.last() == Some(&"")
        {
            return match_segments(&self.segments, &path_segments[..path_segments.len() - 1]);
        }
        false
    }
}

/// `!` prefixes negate a pattern; `!(` introduces an extglob instead.
fn split_negation(pattern: &str) -> (bool, &str) {
    let mut rest = pattern;
    let mut negated = false;
    while let Some(stripped) = rest.strip_prefix('!') {
        if stripped.starts_with('(') {
            break;
        }
        negated = !negated;
        rest = stripped;
    }
    (negated, rest)
}

fn match_segments(patterns: &[Segment], path: &[&str]) -> bool {
    match patterns.split_first() {
        None => path.is_empty(),
        Some((Segment::GlobStar, rest)) => {
            for consumed in 0..=path.len() {
                if consumed > 0 && is_relative_segment(path[consumed - 1]) {
                    break;
                }
                if match_segments(rest, &path[consumed..]) {
                    return true;
                }
            }
            false
        }
        Some((segment, rest)) => match path.split_first() {
            Some((head, tail)) => {
                segment_matches(segment, head) && match_segments(rest, tail)
            }
            None => false,
        },
    }
}

fn is_relative_segment(segment: &str) -> bool {
    segment == "." || segment == ".."
}

fn segment_matches(segment: &Segment, text: &str) -> bool {
    let Segment::Single {
        nodes,
        requires_nonempty,
        literal,
    } = segment
    else {
        return true;
    };
    if let Some(literal) = literal {
        return literal == text;
    }
    // With `dot: true`, wildcards match leading dots but never a `.`/`..` segment.
    if is_relative_segment(text) {
        return false;
    }
    if *requires_nonempty && text.is_empty() {
        return false;
    }
    match_nodes(nodes, text)
}

/// Backtracking matcher for the wildcard nodes of a single path segment.
fn match_nodes(nodes: &[Node], text: &str) -> bool {
    let Some((node, rest)) = nodes.split_first() else {
        return text.is_empty();
    };
    match node {
        Node::Literal(literal) => text
            .strip_prefix(literal.as_str())
            .is_some_and(|tail| match_nodes(rest, tail)),
        Node::AnyChar => {
            let mut chars = text.chars();
            chars.next().is_some() && match_nodes(rest, chars.as_str())
        }
        Node::Star => split_points(text).any(|index| match_nodes(rest, &text[index..])),
        Node::Class {
            raw,
            negated,
            items,
        } => {
            if let Some(tail) = text.strip_prefix(raw.as_str()) {
                if match_nodes(rest, tail) {
                    return true;
                }
            }
            let mut chars = text.chars();
            match chars.next() {
                Some(c) => class_contains(items, c) != *negated && match_nodes(rest, chars.as_str()),
                None => false,
            }
        }
        Node::Alternation(alternatives) => alternatives.iter().any(|alternative| {
            let mut combined = alternative.clone();
            combined.extend_from_slice(rest);
            match_nodes(&combined, text)
        }),
        Node::Repeat {
            alternatives,
            min,
            max,
        } => match_repeat(alternatives, *min, *max, rest, text),
        Node::Negated(alternatives) => split_points(text).any(|index| {
            let candidate = &text[..index];
            !alternatives
                .iter()
                .any(|alternative| match_nodes(alternative, candidate))
                && match_nodes(rest, &text[index..])
        }),
    }
}

/// Every byte index at which `text` can be split on a character boundary, shortest first, matching
/// the lazy quantifiers picomatch emits.
fn split_points(text: &str) -> impl Iterator<Item = usize> + '_ {
    (0..=text.len()).filter(move |index| text.is_char_boundary(*index))
}

fn match_repeat(
    alternatives: &[Vec<Node>],
    min: usize,
    max: Option<usize>,
    rest: &[Node],
    text: &str,
) -> bool {
    if min == 0 && max != Some(0) && match_nodes(rest, text) {
        return true;
    }
    if max == Some(0) {
        return match_nodes(rest, text);
    }
    for index in split_points(text).skip(1) {
        let candidate = &text[..index];
        if !alternatives
            .iter()
            .any(|alternative| match_nodes(alternative, candidate))
        {
            continue;
        }
        let next_max = max.map(|value| value - 1);
        if match_repeat(
            alternatives,
            min.saturating_sub(1),
            next_max,
            rest,
            &text[index..],
        ) {
            return true;
        }
    }
    false
}

fn class_contains(items: &[ClassItem], c: char) -> bool {
    items.iter().any(|item| match item {
        ClassItem::Char(expected) => *expected == c,
        ClassItem::Range(start, end) => *start <= c && c <= *end,
    })
}

fn compile_segment(raw: &str) -> Option<Segment> {
    if raw == "**" {
        return Some(Segment::GlobStar);
    }
    let chars: Vec<char> = raw.chars().collect();
    let mut parser = Parser { chars, pos: 0 };
    let nodes = parser.parse_nodes(&[])?;
    if parser.pos != parser.chars.len() {
        return None;
    }
    let requires_nonempty = matches!(
        nodes.first(),
        Some(Node::Star) | Some(Node::Repeat { .. }) | Some(Node::Negated(_))
    );
    let literal = match nodes.as_slice() {
        [] => Some(String::new()),
        [Node::Literal(text)] => Some(text.clone()),
        _ => None,
    };
    Some(Segment::Single {
        nodes,
        requires_nonempty,
        literal,
    })
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn parse_nodes(&mut self, stop: &[char]) -> Option<Vec<Node>> {
        let mut nodes: Vec<Node> = Vec::new();
        while let Some(c) = self.peek() {
            if stop.contains(&c) {
                break;
            }
            match c {
                '*' => {
                    while self.peek() == Some('*') {
                        self.pos += 1;
                    }
                    nodes.push(Node::Star);
                }
                '?' | '+' | '@' | '!' if self.peek_at(1) == Some('(') => {
                    nodes.push(self.parse_extglob(c)?);
                }
                '?' => {
                    nodes.push(Node::AnyChar);
                    self.pos += 1;
                }
                '[' => nodes.push(self.parse_class()),
                '{' => nodes.push(self.parse_brace()?),
                '\\' => {
                    self.pos += 1;
                    let escaped = self.peek().unwrap_or('\\');
                    self.pos += 1;
                    push_literal(&mut nodes, escaped);
                }
                _ => {
                    self.pos += 1;
                    push_literal(&mut nodes, c);
                }
            }
        }
        Some(nodes)
    }

    fn parse_extglob(&mut self, kind: char) -> Option<Node> {
        self.pos += 2;
        let alternatives = self.parse_alternatives(&['|'], ')')?;
        Some(match kind {
            '?' => Node::Repeat {
                alternatives,
                min: 0,
                max: Some(1),
            },
            '+' => Node::Repeat {
                alternatives,
                min: 1,
                max: None,
            },
            '@' => Node::Alternation(alternatives),
            _ => Node::Negated(alternatives),
        })
    }

    fn parse_brace(&mut self) -> Option<Node> {
        let Some(close) = self.find_brace_close() else {
            self.pos += 1;
            return Some(Node::Literal("{".to_string()));
        };
        let body: String = self.chars[self.pos + 1..close].iter().collect();
        if !body.contains(',') {
            // Without a comma the braces are literal unless they hold a `{a..z}` range.
            if let Some(values) = expand_range(&body) {
                self.pos = close + 1;
                return Some(Node::Alternation(
                    values
                        .into_iter()
                        .map(|value| vec![Node::Literal(value)])
                        .collect(),
                ));
            }
            self.pos += 1;
            return Some(Node::Literal("{".to_string()));
        }
        self.pos += 1;
        let alternatives = self.parse_alternatives(&[','], '}')?;
        Some(Node::Alternation(alternatives))
    }

    /// Parses `a<sep>b<sep>c<close>`, consuming the closing delimiter.
    fn parse_alternatives(&mut self, separators: &[char], close: char) -> Option<Vec<Vec<Node>>> {
        let mut stop = separators.to_vec();
        stop.push(close);
        let mut alternatives = Vec::new();
        loop {
            alternatives.push(self.parse_nodes(&stop)?);
            match self.peek() {
                Some(c) if c == close => {
                    self.pos += 1;
                    return Some(alternatives);
                }
                Some(_) => self.pos += 1,
                None => return None,
            }
        }
    }

    fn find_brace_close(&self) -> Option<usize> {
        let mut depth = 0usize;
        let mut index = self.pos;
        while index < self.chars.len() {
            match self.chars[index] {
                '\\' => index += 1,
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(index);
                    }
                }
                _ => {}
            }
            index += 1;
        }
        None
    }

    fn parse_class(&mut self) -> Node {
        let Some(close) = self.find_class_close() else {
            self.pos += 1;
            return Node::Literal("[".to_string());
        };
        let raw: String = self.chars[self.pos..=close].iter().collect();
        let mut inner: Vec<char> = self.chars[self.pos + 1..close].to_vec();
        self.pos = close + 1;
        let negated = matches!(inner.first(), Some('!') | Some('^'));
        if negated {
            inner.remove(0);
        }
        Node::Class {
            raw,
            negated,
            items: parse_class_items(&inner),
        }
    }

    fn find_class_close(&self) -> Option<usize> {
        let mut index = self.pos + 1;
        if matches!(self.chars.get(index), Some('!') | Some('^')) {
            index += 1;
        }
        if self.chars.get(index) == Some(&']') {
            index += 1;
        }
        while index < self.chars.len() {
            match self.chars[index] {
                '\\' => index += 1,
                '[' if self.chars.get(index + 1) == Some(&':') => {
                    while index < self.chars.len() && self.chars[index] != ']' {
                        index += 1;
                    }
                }
                ']' => return Some(index),
                _ => {}
            }
            index += 1;
        }
        None
    }
}

fn push_literal(nodes: &mut Vec<Node>, c: char) {
    match nodes.last_mut() {
        Some(Node::Literal(text)) => text.push(c),
        _ => nodes.push(Node::Literal(c.to_string())),
    }
}

fn parse_class_items(inner: &[char]) -> Vec<ClassItem> {
    let mut items = Vec::new();
    let mut index = 0;
    while index < inner.len() {
        if inner[index] == '[' && inner.get(index + 1) == Some(&':') {
            if let Some(end) = find_posix_class_end(inner, index) {
                let name: String = inner[index..=end].iter().collect();
                items.extend(posix_class_items(&name));
                index = end + 1;
                continue;
            }
        }
        let mut current = inner[index];
        if current == '\\' && index + 1 < inner.len() {
            index += 1;
            current = inner[index];
        }
        if inner.get(index + 1) == Some(&'-') && index + 2 < inner.len() {
            items.push(ClassItem::Range(current, inner[index + 2]));
            index += 3;
        } else {
            items.push(ClassItem::Char(current));
            index += 1;
        }
    }
    items
}

fn find_posix_class_end(inner: &[char], start: usize) -> Option<usize> {
    let mut index = start + 2;
    while index + 1 < inner.len() {
        if inner[index] == ':' && inner[index + 1] == ']' {
            return Some(index + 1);
        }
        index += 1;
    }
    None
}

fn posix_class_items(name: &str) -> Vec<ClassItem> {
    let ranges: &[(char, char)] = match name {
        "[:alnum:]" => &[('a', 'z'), ('A', 'Z'), ('0', '9')],
        "[:alpha:]" => &[('a', 'z'), ('A', 'Z')],
        "[:ascii:]" => &[('\u{0}', '\u{7f}')],
        "[:blank:]" => &[(' ', ' '), ('\t', '\t')],
        "[:cntrl:]" => &[('\u{0}', '\u{1f}'), ('\u{7f}', '\u{7f}')],
        "[:digit:]" => &[('0', '9')],
        "[:graph:]" => &[('\u{21}', '\u{7e}')],
        "[:lower:]" => &[('a', 'z')],
        "[:print:]" => &[('\u{20}', '\u{7e}')],
        "[:space:]" => &[
            (' ', ' '),
            ('\t', '\t'),
            ('\r', '\r'),
            ('\n', '\n'),
            ('\u{b}', '\u{c}'),
        ],
        "[:upper:]" => &[('A', 'Z')],
        "[:word:]" => &[('a', 'z'), ('A', 'Z'), ('0', '9'), ('_', '_')],
        "[:xdigit:]" => &[('0', '9'), ('a', 'f'), ('A', 'F')],
        _ => &[],
    };
    ranges
        .iter()
        .map(|(start, end)| ClassItem::Range(*start, *end))
        .collect()
}

/// `{1..5}` / `{a..e}` ranges, which picomatch expands into an alternation.
fn expand_range(body: &str) -> Option<Vec<String>> {
    let (start, end) = body.split_once("..")?;
    if let (Ok(start), Ok(end)) = (start.parse::<i64>(), end.parse::<i64>()) {
        if (end - start).unsigned_abs() > 10_000 {
            return None;
        }
        return Some(if start <= end {
            (start..=end).map(|value| value.to_string()).collect()
        } else {
            (end..=start).rev().map(|value| value.to_string()).collect()
        });
    }
    let start: Vec<char> = start.chars().collect();
    let end: Vec<char> = end.chars().collect();
    if let ([start], [end]) = (start.as_slice(), end.as_slice()) {
        let (start, end) = (*start as u32, *end as u32);
        return Some(if start <= end {
            (start..=end).filter_map(char::from_u32).map(String::from).collect()
        } else {
            (end..=start)
                .rev()
                .filter_map(char::from_u32)
                .map(String::from)
                .collect()
        });
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn matches(pattern: &str, path: &str) -> bool {
        Glob::new(pattern)
            .unwrap_or_else(|| panic!("failed to compile {pattern:?}"))
            .is_match(path)
    }

    #[test]
    fn globstar_matches_nested_directories() {
        assert!(matches("**/node_modules/**", "src/node_modules/foo.js"));
        assert!(matches("**/node_modules/**", "/abs/src/node_modules/foo.js"));
        assert!(matches("**/node_modules/**", "src/node_modules"));
        assert!(!matches("**/node_modules/**", "../src/app.js"));
    }

    #[test]
    fn globstar_does_not_cross_traversal_prefix() {
        assert!(!matches(
            "**/node_modules/**",
            "../company.reactapp/src/node_modules/foo.js"
        ));
        assert!(!matches("**/node_modules/**", "./src/node_modules/foo.js"));
    }

    #[test]
    fn bare_name_is_anchored() {
        assert!(matches("node_modules", "node_modules"));
        assert!(!matches("node_modules", "src/node_modules"));
    }

    #[test]
    fn single_star_is_segment_scoped() {
        assert!(matches("*-test.js", "a-test.js"));
        assert!(!matches("*-test.js", "x/a-test.js"));
        assert!(matches("**/*-test.js", "/tmp/x/a-test.js"));
    }

    #[test]
    fn directory_patterns() {
        assert!(matches("sub/dir/", "sub/dir/"));
        assert!(matches("sub/dir/**", "sub/dir"));
        assert!(matches("sub/dir/**", "sub/dir/file.js"));
        assert!(matches("**/sub/dir/**", "/tmp/x/sub/dir/file.js"));
    }

    #[test]
    fn collapsing_globstar() {
        assert!(matches("a/**/b", "a/b"));
        assert!(matches("a/**/b", "a/x/b"));
        assert!(matches("a/**/b", "a/x/y/b"));
        assert!(matches("foo/**/*.js", "foo/bar/baz.js"));
    }

    #[test]
    fn brace_expansion() {
        assert!(matches("**/*.{js,ts}", "foo/bar/baz.ts"));
        assert!(!matches("**/*.{js,ts}", "foo/bar/baz.md"));
        assert!(matches("x{1..3}.js", "x2.js"));
        assert!(!matches("x{1..3}.js", "x4.js"));
    }

    #[test]
    fn negation() {
        assert!(matches("!foo.js", "bar.js"));
        assert!(!matches("!foo.js", "foo.js"));
    }

    #[test]
    fn dot_files_match_with_dot_option() {
        assert!(matches(".*", ".babelrc"));
        assert!(matches("**/.git/**", ".git/config"));
        assert!(matches("**/*.{js,ts}", "x/.hidden/y.js"));
    }

    #[test]
    fn relative_segments_are_never_wildcard_matched() {
        assert!(!matches("*", "."));
        assert!(!matches("*", ".."));
        assert!(!matches("**", "./a"));
        assert!(matches("a/./b", "a/./b"));
    }

    #[test]
    fn question_mark_and_classes() {
        assert!(matches("a?c", "abc"));
        assert!(!matches("a?c", "a/c"));
        assert!(matches("[abc]*.js", "a-test.js"));
        assert!(!matches("[abc]*.js", "d-test.js"));
        assert!(matches("[!a]bc", "bbc"));
        assert!(!matches("[!a]bc", "abc"));
    }

    #[test]
    fn extglobs() {
        assert!(matches("+(a|b).js", "a.js"));
        assert!(!matches("+(a|b).js", "c.js"));
        assert!(matches("@(x|y)", "x"));
        assert!(matches("?(y)", "y"));
        assert!(matches("*(z)", "zzz"));
        assert!(matches("!(foo).js", "bar.js"));
        assert!(!matches("!(foo).js", "foo.js"));
    }

    #[test]
    fn adjacent_stars_inside_segment_are_not_globstar() {
        assert!(matches("a**b", "axxb"));
        assert!(!matches("a**b", "a/x/b"));
    }

