pub const MAX_LENGTH: usize = 1024 * 64;

pub const DOT_LITERAL: &str = "\\.";
pub const PLUS_LITERAL: &str = "\\+";
pub const SLASH_LITERAL: &str = "\\/";
pub const ONE_CHAR: &str = "(?=.)";
pub const QMARK: &str = "[^/]";
pub const END_ANCHOR: &str = "(?:\\/|$)";
pub const START_ANCHOR: &str = "(?:^|\\/)";
pub const DOTS_SLASH: &str = "\\.{1,2}(?:\\/|$)";
pub const NO_DOT: &str = "(?!\\.)";
pub const NO_DOTS: &str = "(?!(?:^|\\/)\\.{1,2}(?:\\/|$))";
pub const NO_DOT_SLASH: &str = "(?!\\.{0,1}(?:\\/|$))";
pub const NO_DOTS_SLASH: &str = "(?!\\.{1,2}(?:\\/|$))";
pub const QMARK_NO_DOT: &str = "[^.\\/]";
pub const STAR: &str = "[^/]*?";

/// `POSIX_REGEX_SOURCE`: character class sources for `[:alpha:]` style expressions.
pub fn posix_regex_source(name: &str) -> Option<&'static str> {
    Some(match name {
        "alnum" => "a-zA-Z0-9",
        "alpha" => "a-zA-Z",
        "ascii" => "\\x00-\\x7F",
        "blank" => " \\t",
        "cntrl" => "\\x00-\\x1F\\x7F",
        "digit" => "0-9",
        "graph" => "\\x21-\\x7E",
        "lower" => "a-z",
        "print" => "\\x20-\\x7E ",
        "punct" => "\\-!\"#$%&'()\\*+,./:;<=>?@[\\]^_`{|}~",
        "space" => " \\t\\r\\n\\v\\f",
        "upper" => "A-Z",
        "word" => "A-Za-z0-9_",
        "xdigit" => "A-Fa-f0-9",
        _ => return None,
    })
}

/// `REPLACEMENTS`: globs rewritten to a cheaper equivalent before parsing.
pub fn replacement(input: &str) -> Option<&'static str> {
    Some(match input {
        "***" => "*",
        "**/**" => "**",
        "**/**/**" => "**",
        _ => return None,
    })
}

pub struct Extglob {
    pub kind: &'static str,
    pub open: &'static str,
    pub close: &'static str,
}

/// `extglobChars`
pub fn extglob_chars(value: char) -> Option<Extglob> {
    Some(match value {
        '!' => Extglob {
            kind: "negate",
            open: "(?:(?!(?:",
            // `))${STAR})`
            close: "))[^/]*?)",
        },
        '?' => Extglob { kind: "qmark", open: "(?:", close: ")?" },
        '+' => Extglob { kind: "plus", open: "(?:", close: ")+" },
        '*' => Extglob { kind: "star", open: "(?:", close: ")*" },
        '@' => Extglob { kind: "at", open: "(?:", close: ")" },
        _ => return None,
    })
}

/// `REGEX_SPECIAL_CHARS`: `/[-*+?.^${}(|)[\]]/`
pub fn is_regex_special(c: char) -> bool {
    matches!(c, '-' | '*' | '+' | '?' | '.' | '^' | '$' | '{' | '}' | '(' | '|' | ')' | '[' | ']')
}

/// The complement of `REGEX_NON_SPECIAL_CHARS`: `/^[^@![\].,$*+?^{}()|\\/]+/`
pub fn is_glob_special(c: char) -> bool {
    matches!(
        c,
        '@' | '!'
            | '['
            | ']'
            | '.'
            | ','
            | '$'
            | '*'
            | '+'
            | '?'
            | '^'
            | '{'
            | '}'
            | '('
            | ')'
            | '|'
            | '\\'
            | '/'
    )
}
