{"command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/glob/parse.rs","file_text":"//! A port of `picomatch/lib/parse.js`.
//!
//! The parser compiles a glob into the source of a JavaScript regular expression. The port follows
//! the original statement by statement so the generated source is byte-identical; options that
//! `jscodeshift` never sets are inlined at their default values (`windows`, `bash`, `capture`,
//! `nobrace`, `noext`, `noglobstar`, `strictSlashes`, `strictBrackets`, `literalBrackets`,
//! `unescape`, `keepQuotes`, `contains`, `posix`, `regex`).

use super::constants::*;

#[derive(Clone, Copy, Debug, Default)]
pub struct Options {
    /// picomatch's `dot`: allow wildcards to match leading dots.
    pub dot: bool,
    /// picomatch's `fastpaths`, which defaults to enabled.
    pub fastpaths: bool,
}

impl Options {
    pub fn new(dot: bool) -> Self {
        Self { dot, fastpaths: true }
    }
}

#[derive(Debug)]
pub struct State {
    pub output: String,
    pub negated: bool,
}

#[derive(Clone, Debug)]
struct Token {
    kind: &'static str,
    value: String,
    output: Option<String>,
    prev: Option<usize>,
    star: bool,
    extglob: bool,
    posix: bool,
    dots: bool,
    comma: bool,
    output_index: usize,
    tokens_index: usize,
}

impl Token {
    fn new(kind: &'static str, value: impl Into<String>) -> Self {
        Self {
            kind,
            value: value.into(),
            output: None,
            prev: None,
            star: false,
            extglob: false,
            posix: false,
            dots: false,
            comma: false,
            output_index: 0,
            tokens_index: 0,
        }
    }

    fn with_output(mut self, output: impl Into<String>) -> Self {
        self.output = Some(output.into());
        self
    }
}

#[derive(Clone, Debug)]
struct ExtglobToken {
    kind: &'static str,
    open: &'static str,
    close: String,
    inner: String,
    prev: Option<usize>,
    parens: usize,
}

/// Removes the last `n` characters from `s`.
fn slice_off_end(s: &mut String, n: usize) {
    if n == 0 {
        return;
    }
    let len = s.chars().count();
    let keep = len.saturating_sub(n);
    let byte_idx = s.char_indices().nth(keep).map(|(i, _)| i).unwrap_or(s.len());
    s.truncate(byte_idx);
}

fn char_len(s: &str) -> usize {
    s.chars().count()
}

/// `utils.escapeLast`
fn escape_last(input: &str, ch: char) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut last = chars.len();
    loop {
        let idx = match chars[..last].iter().rposition(|&c| c == ch) {
            Some(idx) => idx,
            None => return input.to_string(),
        };
        if idx > 0 && chars[idx - 1] == '\\' {
            last = idx;
            continue;
        }
        let mut out: String = chars[..idx].iter().collect();
        out.push('\\');
        out.extend(chars[idx..].iter());
        return out;
    }
}

/// `utils.removePrefix`
fn remove_prefix(input: &str, prefix: &mut String) -> String {
    if let Some(rest) = input.strip_prefix("./") {
        *prefix = "./".to_string();
        return rest.to_string();
    }
    input.to_string()
}

/// `utils.wrapOutput`
fn wrap_output(input: &str, negated: bool) -> String {
    let mut output = format!("^(?:{input})$");
    if negated {
        output = format!("(?:^(?!{output}).*$)");
    }
    output
}

/// JS `\W`: anything outside `[A-Za-z0-9_]`.
fn is_non_word(c: char) -> bool {
    !(c.is_ascii_alphanumeric() || c == '_')
}

/// Applies the `REGEX_SPECIAL_CHARS_BACKREF` (`/(\\?)((\W)(\3*))/g`) replacement used by the
/// fast path inside `parse`.
fn replace_special_chars_backref(
    input: &str,
    mut replace: impl FnMut(BackrefMatch<'_>) -> String,
) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        // `(\\?)` is greedy, so a backslash is consumed as `esc` when a `\W` char follows.
        let mut start = i;
        let mut esc = false;
        if chars[i] == '\\' && i + 1 < chars.len() && is_non_word(chars[i + 1]) {
            esc = true;
            start = i;
            i += 1;
        }
        if !is_non_word(chars[i]) {
            // No match at this position; emit the character(s) verbatim.
            for c in &chars[start..=i] {
                out.push(*c);
            }
            i += 1;
            continue;
        }
        let first = chars[i];
        let mut end = i + 1;
        while end < chars.len() && chars[end] == first {
            end += 1;
        }
        let whole: String = chars[start..end].iter().collect();
        let group_chars: String = chars[i..end].iter().collect();
        let rest: String = chars[i + 1..end].iter().collect();
        out.push_str(&replace(BackrefMatch {
            whole: &whole,
            esc,
            chars: &group_chars,
            first,
            rest: &rest,
            index: start,
        }));
        i = end;
    }
    out
}

struct BackrefMatch<'a> {
    whole: &'a str,
    esc: bool,
    chars: &'a str,
    first: char,
    rest: &'a str,
    index: usize,
}

/// `expandRange`
fn expand_range(args: &[String]) -> String {
    let mut sorted: Vec<String> = args.to_vec();
    sorted.sort();
    let value = format!("[{}]", sorted.join("-"));
    if fancy_regex::Regex::new(&value).is_ok() {
        return value;
    }
    sorted.iter().map(|v| escape_regex(v)).collect::<Vec<_>>().join("..")
}

struct Parser<'a> {
    opts: &'a Options,
    input: Vec<char>,
    len: usize,
    index: i64,
    start: usize,
    consumed: String,
    output: String,
    prefix: String,
    backtrack: bool,
    negated: bool,
    brackets: i64,
    braces: i64,
    parens: i64,
    quotes: i64,
    arena: Vec<Token>,
    tokens: Vec<usize>,
    extglobs: Vec<ExtglobToken>,
    braces_stack: Vec<usize>,
    stack: Vec<&'static str>,
    prev: usize,
    star: String,
    nodot: &'static str,
    qmark_no_dot: &'static str,
}

impl<'a> Parser<'a> {
    fn globstar(&self) -> String {
        format!(
            "(?:(?:(?!{}{}).)*?)",
            START_ANCHOR,
            if self.opts.dot { DOTS_SLASH } else { DOT_LITERAL }
        )
    }

    fn eos(&self) -> bool {
        self.index == self.len as i64 - 1
    }

    fn peek(&self, n: i64) -> Option<char> {
        let i = self.index + n;
        if i < 0 {
            return None;
        }
        self.input.get(i as usize).copied()
    }

    fn advance(&mut self) -> Option<char> {
        self.index += 1;
        if self.index < 0 {
            return None;
        }
        self.input.get(self.index as usize).copied()
    }

    fn remaining(&self) -> String {
        let i = self.index + 1;
        if i < 0 {
            return self.input.iter().collect();
        }
        let i = i as usize;
        if i >= self.input.len() {
            return String::new();
        }
        self.input[i..].iter().collect()
    }

    fn consume(&mut self, value: &str, num: i64) {
        self.consumed.push_str(value);
        self.index += num;
    }

    fn append(&mut self, output: Option<&str>, value: &str) {
        match output {
            Some(output) => self.output.push_str(output),
            None => self.output.push_str(value),
        }
        let value = value.to_string();
        self.consume(&value, 0);
    }

    fn increment(&mut self, kind: &'static str) {
        match kind {
            "parens" => self.parens += 1,
            "brackets" => self.brackets += 1,
            "braces" => self.braces += 1,
            "quotes" => self.quotes += 1,
            _ => unreachable!(),
        }
        self.stack.push(kind);
    }

    fn decrement(&mut self, kind: &'static str) {
        match kind {
            "parens" => self.parens -= 1,
            "brackets" => self.brackets -= 1,
            "braces" => self.braces -= 1,
            "quotes" => self.quotes -= 1,
            _ => unreachable!(),
        }
        self.stack.pop();
    }

    /// `negate()`
    fn negate(&mut self) {
        let mut count = 1;

        while self.peek(1) == Some('!') && (self.peek(2) != Some('(') || self.peek(3) == Some('?')) {
            self.advance();
            self.start += 1;
            count += 1;
        }

        if count % 2 == 0 {
            return;
        }

        self.negated = true;
        self.start += 1;
    }

    fn push(&mut self, mut tok: Token) {
        if self.arena[self.prev].kind == "globstar" {
            let is_brace = self.braces > 0 && (tok.kind == "comma" || tok.kind == "brace");
            let is_extglob = tok.extglob
                || (!self.extglobs.is_empty() && (tok.kind == "pipe" || tok.kind == "paren"));

            if tok.kind != "slash" && tok.kind != "paren" && !is_brace && !is_extglob {
                let prev_output = self.arena[self.prev].output.clone().unwrap_or_default();
                slice_off_end(&mut self.output, char_len(&prev_output));
                let star = self.star.clone();
                let prev = &mut self.arena[self.prev];
                prev.kind = "star";
                prev.value = "*".to_string();
                prev.output = Some(star.clone());
                self.output.push_str(&star);
            }
        }

        if !self.extglobs.is_empty() && tok.kind != "paren" {
            let value = tok.value.clone();
            self.extglobs.last_mut().unwrap().inner.push_str(&value);
        }

        let has_output = tok.output.as_ref().is_some_and(|o| !o.is_empty());
        if !tok.value.is_empty() || has_output {
            let output = tok.output.clone();
            let value = tok.value.clone();
            self.append(output.as_deref(), &value);
        }

        if self.arena[self.prev].kind == "text" && tok.kind == "text" {
            let prev = &mut self.arena[self.prev];
            let base = prev.output.clone().unwrap_or_else(|| prev.value.clone());
            prev.output = Some(base + &tok.value);
            let value = tok.value.clone();
            prev.value.push_str(&value);
            return;
        }

        tok.prev = Some(self.prev);
        self.arena.push(tok);
        let idx = self.arena.len() - 1;
        self.tokens.push(idx);
        self.prev = idx;
    }

    /// `extglobOpen`
    fn extglob_open(&mut self, kind: &'static str, value: char) {
        let chars = extglob_chars(value).expect("extglob char");
        let token = ExtglobToken {
            kind: chars.kind,
            open: chars.open,
            close: chars.close.to_string(),
            inner: String::new(),
            prev: Some(self.prev),
            parens: self.parens.max(0) as usize,
        };

        let output = token.open.to_string();

        self.increment("parens");
        let one_char = if self.output.is_empty() { ONE_CHAR } else { "" };
        self.push(Token::new(kind, value.to_string()).with_output(one_char));
        let advanced = self.advance().map(String::from).unwrap_or_default();
        let mut paren = Token::new("paren", advanced).with_output(output);
        paren.extglob = true;
        self.push(paren);
        self.extglobs.push(token);
    }

    /// `extglobClose`
    fn extglob_close(&mut self, mut token: ExtglobToken, value: String) {
        let mut output = token.close.clone();

        if token.kind == "negate" {
            let mut extglob_star = self.star.clone();

            if char_len(&token.inner) > 1 && token.inner.contains('/') {
                extglob_star = self.globstar();
            }

            let remaining = self.remaining();
            let only_parens = !remaining.is_empty() && remaining.chars().all(|c| c == ')');
            if extglob_star != self.star || self.eos() || only_parens {
                token.close = format!(")$)){extglob_star}");
                output = token.close.clone();
            }

            if token.inner.contains('*') && is_dot_suffix(&remaining) {
                // `/!(*.d).ts` and friends: the trailing literal has to be parsed and folded into
                // the closing group.
                let expression = parse_with(
                    &remaining,
                    &Options { dot: self.opts.dot, fastpaths: false },
                )
                .output;
                token.close = format!("){expression}){extglob_star})");
                output = token.close.clone();
            }

            if token.prev.map(|p| self.arena[p].kind) == Some("bos") {
                // `state.negatedExtglob` is only consumed by picomatch's public `scan`.
            }
        }

        let mut tok = Token::new("paren", value).with_output(output);
        tok.extglob = true;
        self.push(tok);
        self.decrement("parens");
    }
}

/// `/^\.[^\\/.]+$/`
fn is_dot_suffix(rest: &str) -> bool {
    let mut chars = rest.chars();
    if chars.next() != Some('.') {
        return false;
    }
    let mut count = 0;
    for c in chars {
        if c == '\\' || c == '/' || c == '.' {
            return false;
        }
        count += 1;
    }
    count > 0
}

/// `/<([!=]|\w+>)/`
fn has_lookbehind_marker(remaining: &str) -> bool {
    let chars: Vec<char> = remaining.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        if *c != '<' {
            continue;
        }
        match chars.get(i + 1) {
            Some('!') | Some('=') => return true,
            Some(c) if !is_non_word(*c) => {
                let mut j = i + 1;
                while j < chars.len() && !is_non_word(chars[j]) {
                    j += 1;
                }
                if chars.get(j) == Some(&'>') {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

/// `parse(input, options)`
pub fn parse_with(input: &str, opts: &Options) -> State {
    let input = replacement(input).unwrap_or(input);

    if input.chars().count() > MAX_LENGTH {
        // picomatch throws a SyntaxError; `makeRe` callers surface it as a non-matching regex.
        return State { output: "$^".to_string(), negated: false };
    }

    let star = STAR.to_string();
    let nodot = if opts.dot { "" } else { NO_DOT };
    let qmark_no_dot = if opts.dot { QMARK } else { QMARK_NO_DOT };

    let bos = Token::new("bos", "").with_output("");

    let mut prefix = String::new();
    let input = remove_prefix(input, &mut prefix);
    let chars: Vec<char> = input.chars().collect();
    let len = chars.len();

    let mut p = Parser {
        opts,
        input: chars,
        len,
        index: -1,
        start: 0,
        consumed: String::new(),
        output: String::new(),
        prefix,
        backtrack: false,
        negated: false,
        brackets: 0,
        braces: 0,
        parens: 0,
        quotes: 0,
        arena: vec![bos],
        tokens: vec![0],
        extglobs: Vec::new(),
        braces_stack: Vec::new(),
        stack: Vec::new(),
        prev: 0,
        star,
        nodot,
        qmark_no_dot,
    };

    // Fast paths
    if opts.fastpaths && !starts_or_contains_special(&input) {
        let mut backslashes = false;

        let star = p.star.clone();
        let qmark_no_dot = p.qmark_no_dot;
        let mut output = replace_special_chars_backref(&input, |m| {
            if m.first == '\\' {
                backslashes = true;
                return m.whole.to_string();
            }

            if m.first == '?' {
                if m.esc {
                    return format!(
                        "\\?{}",
                        if m.rest.is_empty() { String::new() } else { QMARK.repeat(char_len(m.rest)) }
                    );
                }
                if m.index == 0 {
                    return format!(
                        "{}{}",
                        qmark_no_dot,
                        if m.rest.is_empty() { String::new() } else { QMARK.repeat(char_len(m.rest)) }
                    );
                }
                return QMARK.repeat(char_len(m.chars));
            }

            if m.first == '.' {
                return DOT_LITERAL.repeat(char_len(m.chars));
            }

            if m.first == '*' {
                if m.esc {
                    return format!("\\*{}", if m.rest.is_empty() { "" } else { star.as_str() });
                }
                return star.clone();
            }

            if m.esc {
                m.whole.to_string()
            } else {
                format!("\\{}", m.whole)
            }
        });

        if backslashes {
            output = collapse_backslashes(&output);
        }

        return State { output: wrap_output(&output, false), negated: false };
    }

    // Tokenize input until we reach end-of-string
    while !p.eos() {
        let mut value = match p.advance() {
            Some(c) => c.to_string(),
            None => String::new(),
        };

        if value == "\u{0}" {
            continue;
        }

        // Escaped characters
        if value == "\\" {
            let next = p.peek(1);

            if next == Some('/') {
                continue;
            }

            if next == Some('.') || next == Some(';') {
                continue;
            }

            if next.is_none() {
                value.push('\\');
                p.push(Token::new("text", value));
                continue;
            }

            // collapse slashes to reduce potential for exploits
            let remaining = p.remaining();
            let leading = remaining.chars().take_while(|c| *c == '\\').count();
            if leading > 2 {
                p.index += leading as i64;
                if leading % 2 != 0 {
                    value.push('\\');
                }
            }

            if let Some(c) = p.advance() {
                value.push(c);
            }

            if p.brackets == 0 {
                p.push(Token::new("text", value));
                continue;
            }
        }

        // Inside a regex character class
        if p.brackets > 0
            && (value != "]"
                || p.arena[p.prev].value == "["
                || p.arena[p.prev].value == "[^")
        {
            if value == ":" {
                let inner: String = p.arena[p.prev].value.chars().skip(1).collect();
                if inner.contains('[') {
                    p.arena[p.prev].posix = true;

                    if inner.contains(':') {
                        let prev_value = p.arena[p.prev].value.clone();
                        let idx = prev_value.rfind('[').unwrap();
                        let pre: String = prev_value[..idx].to_string();
                        let rest: String = prev_value[idx..].chars().skip(2).collect();
                        if let Some(posix) = posix_regex_source(&rest) {
                            p.arena[p.prev].value = pre + posix;
                            p.backtrack = true;
                            p.advance();

                            let bos_output_empty =
                                p.arena[0].output.as_ref().is_none_or(|o| o.is_empty());
                            if bos_output_empty && p.tokens.iter().position(|&t| t == p.prev) == Some(1)
                            {
                                p.arena[0].output = Some(ONE_CHAR.to_string());
                            }
                            continue;
                        }
                    }
                }
            }

            if (value == "[" && p.peek(1) != Some(':')) || (value == "-" && p.peek(1) == Some(']')) {
                value = format!("\\{value}");
            }

            if value == "]" && (p.arena[p.prev].value == "[" || p.arena[p.prev].value == "[^") {
                value = format!("\\{value}");
            }

            p.arena[p.prev].value.push_str(&value);
            p.append(None, &value);
            continue;
        }

        // Inside a quoted string
        if p.quotes == 1 && value != "\"" {
            value = escape_regex(&value);
            p.arena[p.prev].value.push_str(&value);
            p.append(None, &value);
            continue;
        }

        // Double quotes
        if value == "\"" {
            p.quotes = if p.quotes == 1 { 0 } else { 1 };
            continue;
        }

        // Parentheses
        if value == "(" {
            p.increment("parens");
            p.push(Token::new("paren", value));
            continue;
        }

        if value == ")" {
            let close = p
                .extglobs
                .last()
                .is_some_and(|e| p.parens == e.parens as i64 + 1);
            if close {
                let token = p.extglobs.pop().unwrap();
                p.extglob_close(token, value);
                continue;
            }

            let output = if p.parens != 0 { ")" } else { "\\)" };
            p.push(Token::new("paren", value).with_output(output));
            p.decrement("parens");
            continue;
        }

        // Square brackets
        if value == "[" {
            if !p.remaining().contains(']') {
                value = format!("\\{value}");
            } else {
                p.increment("brackets");
            }

            p.push(Token::new("bracket", value));
            continue;
        }

        if value == "]" {
            if p.arena[p.prev].kind == "bracket" && char_len(&p.arena[p.prev].value) == 1 {
                let output = format!("\\{value}");
                p.push(Token::new("text", value).with_output(output));
                continue;
            }

            if p.brackets == 0 {
                let output = format!("\\{value}");
                p.push(Token::new("text", value).with_output(output));
                continue;
            }

            p.decrement("brackets");

            let prev_value: String = p.arena[p.prev].value.chars().skip(1).collect();
            if !p.arena[p.prev].posix
                && prev_value.starts_with('^')
                && !prev_value.contains('/')
            {
                value = format!("/{value}");
            }

            p.arena[p.prev].value.push_str(&value);
            p.append(None, &value);

            if has_regex_chars(&prev_value) {
                continue;
            }

            let escaped = escape_regex(&p.arena[p.prev].value);
            let prev_len = char_len(&p.arena[p.prev].value);
            slice_off_end(&mut p.output, prev_len);

            // when the user specifies nothing, try to match both
            let combined = format!("(?:{}|{})", escaped, p.arena[p.prev].value);
            p.arena[p.prev].value = combined.clone();
            p.output.push_str(&combined);
            continue;
        }

        // Braces
        if value == "{" {
            p.increment("braces");

            let mut open = Token::new("brace", value).with_output("(");
            open.output_index = char_len(&p.output);
            open.tokens_index = p.tokens.len();

            p.push(open);
            let idx = p.prev;
            p.braces_stack.push(idx);
            continue;
        }

        if value == "}" {
            let brace = p.braces_stack.last().copied();

            let brace = match brace {
                Some(brace) => brace,
                None => {
                    let output = value.clone();
                    p.push(Token::new("text", value).with_output(output));
                    continue;
                }
            };

            let mut output = ")".to_string();

            if p.arena[brace].dots {
                let arr = p.tokens.clone();
                let mut range: Vec<String> = Vec::new();

                for i in (0..arr.len()).rev() {
                    p.tokens.pop();
                    if p.arena[arr[i]].kind == "brace" {
                        break;
                    }
                    if p.arena[arr[i]].kind != "dots" {
                        range.insert(0, p.arena[arr[i]].value.clone());
                    }
                }

                output = expand_range(&range);
                p.backtrack = true;
            }

            if !p.arena[brace].comma && !p.arena[brace].dots {
                let output_index = p.arena[brace].output_index;
                let tokens_index = p.arena[brace].tokens_index;
                let out: String = p.output.chars().take(output_index).collect();
                let toks: Vec<usize> = p.tokens[tokens_index..].to_vec();
                p.arena[brace].value = "\\{".to_string();
                p.arena[brace].output = Some("\\{".to_string());
                value = "\\}".to_string();
                output = "\\}".to_string();
                p.output = out;
                for t in toks {
                    let piece = p.arena[t]
                        .output
                        .clone()
                        .unwrap_or_else(|| p.arena[t].value.clone());
                    p.output.push_str(&piece);
                }
            }

            p.push(Token::new("brace", value).with_output(output));
            p.decrement("braces");
            p.braces_stack.pop();
            continue;
        }

        // Pipes
        if value == "|" {
            p.push(Token::new("text", value));
            continue;
        }

        // Commas
        if value == "," {
            let mut output = value.clone();

            if let Some(&brace) = p.braces_stack.last() {
                if p.stack.last() == Some(&"braces") {
                    p.arena[brace].comma = true;
                    output = "|".to_string();
                }
            }

            p.push(Token::new("comma", value).with_output(output));
            continue;
        }

        // Slashes
        if value == "/" {
            // if the beginning of the glob is "./", advance the start
            if p.arena[p.prev].kind == "dot" && p.index == p.start as i64 + 1 {
                p.start = (p.index + 1) as usize;
                p.consumed = String::new();
                p.output = String::new();
                p.tokens.pop();
                p.prev = 0;
                continue;
            }

            p.push(Token::new("slash", value).with_output(SLASH_LITERAL));
            continue;
        }

        // Dots
        if value == "." {
            if p.braces > 0 && p.arena[p.prev].kind == "dot" {
                if p.arena[p.prev].value == "." {
                    p.arena[p.prev].output = Some(DOT_LITERAL.to_string());
                }
                let brace = *p.braces_stack.last().expect("brace");
                p.arena[p.prev].kind = "dots";
                let output = p.arena[p.prev]
                    .output
                    .clone()
                    .unwrap_or_default()
                    + &value;
                p.arena[p.prev].output = Some(output);
                p.arena[p.prev].value.push_str(&value);
                p.arena[brace].dots = true;
                continue;
            }

            if p.braces + p.parens == 0
                && p.arena[p.prev].kind != "bos"
                && p.arena[p.prev].kind != "slash"
            {
                p.push(Token::new("text", value).with_output(DOT_LITERAL));
                continue;
            }

            p.push(Token::new("dot", value).with_output(DOT_LITERAL));
            continue;
        }

        // Question marks
        if value == "?" {
            let is_group = p.arena[p.prev].value == "(";
            if !is_group && p.peek(1) == Some('(') && p.peek(2) != Some('?') {
                p.extglob_open("qmark", '?');
                continue;
            }

            if p.arena[p.prev].kind == "paren" {
                let next = p.peek(1);
                let mut output = value.clone();

                let next_is_special = matches!(next, Some('!') | Some('=') | Some('<') | Some(':'));
                if (p.arena[p.prev].value == "(" && !next_is_special)
                    || (next == Some('<') && !has_lookbehind_marker(&p.remaining()))
                {
                    output = format!("\\{value}");
                }

                p.push(Token::new("text", value).with_output(output));
                continue;
            }

            if !p.opts.dot
                && (p.arena[p.prev].kind == "slash" || p.arena[p.prev].kind == "bos")
            {
                p.push(Token::new("qmark", value).with_output(QMARK_NO_DOT));
                continue;
            }

            p.push(Token::new("qmark", value).with_output(QMARK));
            continue;
        }

        // Exclamation
        if value == "!" {
            if p.peek(1) == Some('(') {
                let peek3 = p.peek(3);
                let peek3_special = matches!(peek3, Some('!') | Some('=') | Some('<') | Some(':'));
                if p.peek(2) != Some('?') || !peek3_special {
                    p.extglob_open("negate", '!');
                    continue;
                }
            }

            if p.index == 0 {
                p.negate();
                continue;
            }
        }

        // Plus
        if value == "+" {
            if p.peek(1) == Some('(') && p.peek(2) != Some('?') {
                p.extglob_open("plus", '+');
                continue;
            }

            if p.arena[p.prev].value == "(" {
                p.push(Token::new("plus", value).with_output(PLUS_LITERAL));
                continue;
            }

            let prev_kind = p.arena[p.prev].kind;
            if prev_kind == "bracket" || prev_kind == "paren" || prev_kind == "brace" || p.parens > 0
            {
                p.push(Token::new("plus", value));
                continue;
            }

            p.push(Token::new("plus", PLUS_LITERAL));
            continue;
        }

        // At
        if value == "@" {
            if p.peek(1) == Some('(') && p.peek(2) != Some('?') {
                let mut tok = Token::new("at", value).with_output("");
                tok.extglob = true;
                p.push(tok);
                continue;
            }

            p.push(Token::new("text", value));
            continue;
        }

        // Plain text
        if value != "*" {
            if value == "$" || value == "^" {
                value = format!("\\{value}");
            }

            let remaining = p.remaining();
            let run: String = remaining.chars().take_while(|c| !is_glob_special(*c)).collect();
            if !run.is_empty() {
                value.push_str(&run);
                p.index += char_len(&run) as i64;
            }

            p.push(Token::new("text", value));
            continue;
        }

        // Stars
        if p.arena[p.prev].kind == "globstar" || p.arena[p.prev].star {
            let star = p.star.clone();
            let prev = &mut p.arena[p.prev];
            prev.kind = "star";
            prev.star = true;
            prev.value.push_str(&value);
            prev.output = Some(star);
            p.backtrack = true;
            p.consume(&value.clone(), 0);
            continue;
        }

        let mut rest = p.remaining();
        if starts_with_extglob_paren(&rest) {
            p.extglob_open("star", '*');
            continue;
        }

        if p.arena[p.prev].kind == "star" {
            let prior = p.arena[p.prev].prev.expect("star has a previous token");
            let before = p.arena[prior].prev;
            let prior_kind = p.arena[prior].kind;
            let is_start = prior_kind == "slash" || prior_kind == "bos";
            let after_star = before
                .map(|b| p.arena[b].kind == "star" || p.arena[b].kind == "globstar")
                .unwrap_or(false);

            let is_brace = p.braces > 0 && (prior_kind == "comma" || prior_kind == "brace");
            let is_extglob =
                !p.extglobs.is_empty() && (prior_kind == "pipe" || prior_kind == "paren");
            if !is_start && prior_kind != "paren" && !is_brace && !is_extglob {
                p.push(Token::new("star", value).with_output(""));
                continue;
            }

            // strip consecutive `/**/`
            while rest.chars().take(3).collect::<String>() == "/**" {
                let after = p.input.get((p.index + 4) as usize).copied();
                if let Some(after) = after {
                    if after != '/' {
                        break;
                    }
                }
                rest = rest.chars().skip(3).collect();
                p.consume("/**", 3);
            }

            if prior_kind == "bos" && p.eos() {
                let globstar = p.globstar();
                let prev = p.prev;
                p.arena[prev].kind = "globstar";
                p.arena[prev].value.push_str(&value);
                p.arena[prev].output = Some(globstar.clone());
                p.output = globstar;
                p.consume(&value.clone(), 0);
                continue;
            }

            if prior_kind == "slash"
                && p.arena[p.arena[prior].prev.expect("slash has a previous token")].kind != "bos"
                && !after_star
                && p.eos()
            {
                let prior_output = p.arena[prior].output.clone().unwrap_or_default();
                let prev_output = p.arena[p.prev].output.clone().unwrap_or_default();
                slice_off_end(
                    &mut p.output,
                    char_len(&prior_output) + char_len(&prev_output),
                );
                let new_prior_output = format!("(?:{prior_output}");
                p.arena[prior].output = Some(new_prior_output.clone());

                let new_prev_output = format!("{}|$)", p.globstar());
                let prev = p.prev;
                p.arena[prev].kind = "globstar";
                p.arena[prev].output = Some(new_prev_output.clone());
                p.arena[prev].value.push_str(&value);
                p.output.push_str(&new_prior_output);
                p.output.push_str(&new_prev_output);
                p.consume(&value.clone(), 0);
                continue;
            }

            if prior_kind == "slash"
                && p.arena[p.arena[prior].prev.expect("slash has a previous token")].kind != "bos"
                && rest.starts_with('/')
            {
                let end = if rest.chars().nth(1).is_some() { "|$" } else { "" };

                let prior_output = p.arena[prior].output.clone().unwrap_or_default();
                let prev_output = p.arena[p.prev].output.clone().unwrap_or_default();
                slice_off_end(
                    &mut p.output,
                    char_len(&prior_output) + char_len(&prev_output),
                );
                let new_prior_output = format!("(?:{prior_output}");
                p.arena[prior].output = Some(new_prior_output.clone());

                let new_prev_output = format!(
                    "{}{}|{}{})",
                    p.globstar(),
                    SLASH_LITERAL,
                    SLASH_LITERAL,
                    end
                );
                let prev = p.prev;
                p.arena[prev].kind = "globstar";
                p.arena[prev].output = Some(new_prev_output.clone());
                p.arena[prev].value.push_str(&value);

                p.output.push_str(&new_prior_output);
                p.output.push_str(&new_prev_output);

                let advanced = p.advance().map(String::from).unwrap_or_default();
                p.consume(&format!("{value}{advanced}"), 0);

                p.push(Token::new("slash", "/").with_output(""));
                continue;
            }

            if prior_kind == "bos" && rest.starts_with('/') {
                let output = format!("(?:^|{}|{}{})", SLASH_LITERAL, p.globstar(), SLASH_LITERAL);
                let prev = p.prev;
                p.arena[prev].kind = "globstar";
                p.arena[prev].value.push_str(&value);
                p.arena[prev].output = Some(output.clone());
                p.output = output;
                let advanced = p.advance().map(String::from).unwrap_or_default();
                p.consume(&format!("{value}{advanced}"), 0);
                p.push(Token::new("slash", "/").with_output(""));
                continue;
            }

            // remove single star from output
            let prev_output = p.arena[p.prev].output.clone().unwrap_or_default();
            slice_off_end(&mut p.output, char_len(&prev_output));

            // reset previous token to globstar
            let globstar = p.globstar();
            let prev = p.prev;
            p.arena[prev].kind = "globstar";
            p.arena[prev].output = Some(globstar.clone());
            p.arena[prev].value.push_str(&value);

            p.output.push_str(&globstar);
            p.consume(&value.clone(), 0);
            continue;
        }

        let mut token = Token::new("star", value).with_output(p.star.clone());

        if p.index == p.start as i64
            || p.arena[p.prev].kind == "slash"
            || p.arena[p.prev].kind == "dot"
        {
            let extra = if p.arena[p.prev].kind == "dot" {
                NO_DOT_SLASH
            } else if p.opts.dot {
                NO_DOTS_SLASH
            } else {
                p.nodot
            };
            p.output.push_str(extra);
            let prev = p.prev;
            let prev_output = p.arena[prev].output.clone().unwrap_or_default();
            p.arena[prev].output = Some(prev_output + extra);

            if p.peek(1) != Some('*') {
                p.output.push_str(ONE_CHAR);
                let prev_output = p.arena[prev].output.clone().unwrap_or_default();
                p.arena[prev].output = Some(prev_output + ONE_CHAR);
            }
        }

        // `token.output` was captured before the prefix adjustments above, matching picomatch.
        token.output = Some(p.star.clone());
        p.push(token);
    }

    while p.brackets > 0 {
        p.output = escape_last(&p.output, '[');
        p.decrement("brackets");
    }

    while p.parens > 0 {
        p.output = escape_last(&p.output, '(');
        p.decrement("parens");
    }

    while p.braces > 0 {
        p.output = escape_last(&p.output, '{');
        p.decrement("braces");
    }

    if p.arena[p.prev].kind == "star" || p.arena[p.prev].kind == "bracket" {
        p.push(Token::new("maybe_slash", "").with_output(format!("{SLASH_LITERAL}?")));
    }

    // rebuild the output if we had to backtrack at any point
    if p.backtrack {
        p.output = String::new();

        for &t in &p.tokens {
            let piece = p.arena[t]
                .output
                .clone()
                .unwrap_or_else(|| p.arena[t].value.clone());
            p.output.push_str(&piece);
        }
    }

    State { output: p.output, negated: p.negated }
}

/// `/(^[*!]|[/()[\]{}"])/`
fn starts_or_contains_special(input: &str) -> bool {
    let mut chars = input.chars();
    match chars.next() {
        Some('*') | Some('!') => return true,
        None => return false,
        _ => {}
    }
    input
        .chars()
        .any(|c| matches!(c, '/' | '(' | ')' | '[' | ']' | '{' | '}' | '"'))
}

/// `/^\([^?]/`
fn starts_with_extglob_paren(rest: &str) -> bool {
    let mut chars = rest.chars();
    chars.next() == Some('(') && matches!(chars.next(), Some(c) if c != '?')
}

/// `output.replace(/\\+/g, m => m.length % 2 === 0 ? '\\\\' : (m ? '\\' : ''))`
fn collapse_backslashes(output: &str) -> String {
    let chars: Vec<char> = output.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] != '\\' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        let start = i;
        while i < chars.len() && chars[i] == '\\' {
            i += 1;
        }
        let run = i - start;
        out.push_str(if run % 2 == 0 { "\\\\" } else { "\\" });
    }
    out
}

/// `parse.fastpaths(input, options)`
pub fn fastpaths(input: &str, opts: &Options) -> Option<String> {
    if input.chars().count() > MAX_LENGTH {
        return None;
    }

    let input = replacement(input).unwrap_or(input);

    let nodot = if opts.dot { NO_DOTS } else { NO_DOT };
    let slash_dot = if opts.dot { NO_DOTS_SLASH } else { NO_DOT };
    let star = STAR;
    let globstar = format!(
        "(?:(?:(?!{}{}).)*?)",
        START_ANCHOR,
        if opts.dot { DOTS_SLASH } else { DOT_LITERAL }
    );

    fn create(
        str: &str,
        nodot: &str,
        slash_dot: &str,
        star: &str,
        globstar: &str,
    ) -> Option<String> {
        Some(match str {
            "*" => format!("{nodot}{ONE_CHAR}{star}"),
            ".*" => format!("{DOT_LITERAL}{ONE_CHAR}{star}"),
            "*.*" => format!("{nodot}{star}{DOT_LITERAL}{ONE_CHAR}{star}"),
            "*/*" => format!("{nodot}{star}{SLASH_LITERAL}{ONE_CHAR}{slash_dot}{star}"),
            "**" => format!("{nodot}{globstar}"),
            "**/*" => {
                format!("(?:{nodot}{globstar}{SLASH_LITERAL})?{slash_dot}{ONE_CHAR}{star}")
            }
            "**/*.*" => format!(
                "(?:{nodot}{globstar}{SLASH_LITERAL})?{slash_dot}{star}{DOT_LITERAL}{ONE_CHAR}{star}"
            ),
            "**/.*" => {
                format!("(?:{nodot}{globstar}{SLASH_LITERAL})?{DOT_LITERAL}{ONE_CHAR}{star}")
            }
            _ => {
                // `/^(.*?)\.(\w+)$/`
                let (head, ext) = split_extension(str)?;
                let source = create(&head, nodot, slash_dot, star, globstar)?;
                return Some(source + DOT_LITERAL + &ext);
            }
        })
    }

    let mut prefix = String::new();
    let output = remove_prefix(input, &mut prefix);
    let mut source = create(&output, nodot, slash_dot, star, &globstar)?;
    source += &format!("{SLASH_LITERAL}?");
    Some(source)
}

/// `/^(.*?)\.(\w+)$/`, which is lazy in the head so it splits at the first suitable dot.
fn split_extension(str: &str) -> Option<(String, String)> {
    let chars: Vec<char> = str.chars().collect();
    for i in 0..chars.len() {
        if chars[i] != '.' {
            continue;
        }
        let ext = &chars[i + 1..];
        if !ext.is_empty() && ext.iter().all(|c| !is_non_word(*c)) {
            return Some((chars[..i].iter().collect(), ext.iter().collect()));
        }
    }
    None
}
