{"command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/glob/mod.rs","file_text":"//! A port of the `picomatch` glob matcher, as used by `src/ignoreFiles.js`.
//!
//! `picomatch` compiles a glob into a JavaScript regular expression; the parser is ported verbatim
//! in [`parse`] so the generated source is identical, and `fancy_regex` evaluates it (the sources
//! use lookarounds, which the `regex` crate does not support).

mod constants;
mod parse;

use std::sync::OnceLock;

use fancy_regex::Regex;

pub use parse::Options;

/// A compiled glob, equivalent to the function returned by `picomatch(pattern, options)`.
pub struct Matcher {
    regex: Option<Regex>,
    /// Set when the regex source is rejected by `fancy_regex`; matching then always fails, which
    /// mirrors `picomatch` bailing out on an invalid source.
    basename: bool,
    regex_basename: OnceLock<Option<Regex>>,
}

impl Matcher {
    /// `picomatch(pattern, options)`
    pub fn new(pattern: &str, options: Options) -> Self {
        let source = make_re_source(pattern, options);
        Self {
            regex: Regex::new(&source).ok(),
            basename: false,
            regex_basename: OnceLock::new(),
        }
    }

    /// `picomatch.isMatch(input, pattern, options)` for a single pattern.
    pub fn is_match(&self, input: &str) -> bool {
        let _ = (&self.basename, &self.regex_basename);
        match &self.regex {
            Some(regex) => regex.is_match(input).unwrap_or(false),
            None => false,
        }
    }
}

/// `picomatch.makeRe(pattern, options)`, returning the regex source.
pub fn make_re_source(pattern: &str, options: Options) -> String {
    let mut parsed: Option<String> = None;

    if options.fastpaths {
        parsed = parse::fastpaths(pattern, &options);
    }

    let (output, negated) = match parsed {
        Some(output) => (output, false),
        None => {
            let state = parse::parse_with(pattern, &parse::Options { fastpaths: false, ..options });
            (state.output, state.negated)
        }
    };

    let mut source = format!("^(?:{output})$");
    if negated {
        source = format!("^(?!{source}).*$");
    }
    source
}

/// `picomatch.isMatch(input, pattern, options)`
pub fn is_match(input: &str, pattern: &str, options: Options) -> bool {
    Matcher::new(pattern, options).is_match(input)
}
