mod constants;
mod parse;

use fancy_regex::Regex;

pub use parse::Options;

/// A compiled glob, equivalent to the function returned by `picomatch(pattern, options)`.
pub struct Matcher {
    glob: String,
    /// `None` when the source is rejected by the regex engine. `picomatch.toRegex` falls back to
    /// `/$^/` in that case, which never matches.
    regex: Option<Regex>,
}

impl Matcher {
    /// `picomatch(pattern, options)`
    pub fn new(pattern: &str, options: Options) -> Self {
        let source = make_re_source(pattern, options);
        Self { glob: pattern.to_string(), regex: Regex::new(&source).ok() }
    }

    /// `picomatch.test(input, regex, options, { glob })` reduced to its boolean result.
    pub fn is_match(&self, input: &str) -> bool {
        if input.is_empty() {
            return false;
        }
        if input == self.glob {
            return true;
        }
        match &self.regex {
            Some(regex) => regex.is_match(input).unwrap_or(false),
            None => false,
        }
    }
}

/// `picomatch.makeRe(pattern, options)`, returning the regex source.
pub fn make_re_source(pattern: &str, options: Options) -> String {
    let mut parsed: Option<String> = None;

    let first = pattern.chars().next();
    if options.fastpaths && (first == Some('.') || first == Some('*')) {
        parsed = parse::fastpaths(pattern, &options);
    }

    let (output, negated) = match parsed.filter(|o| !o.is_empty()) {
        Some(output) => (output, false),
        None => {
            let state = parse::parse_with(pattern, &options);
            (state.output, state.negated)
        }
    };

    // `picomatch.compileRe`
    let mut source = format!("^(?:{output})$");
    if negated {
        source = format!("^(?!{source}).*$");
    }
    source
}

/// `picomatch.isMatch(input, pattern, options)` for a single pattern.
pub fn is_match(input: &str, pattern: &str, options: Options) -> bool {
    Matcher::new(pattern, options).is_match(input)
}
