{"command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/glob/jsregex.rs","file_text":"//! A model of the parts of JavaScript's `RegExp` that `picomatch` depends on.
//!
//! `picomatch` builds a regular expression source string and relies on two behaviors of the
//! JavaScript engine: `new RegExp(source)` throws a `SyntaxError` for a handful of patterns a glob
//! can produce (`picomatch.toRegex` then falls back to `/$^/`), and `RegExp.prototype.source`
//! normalizes the pattern it was given (`/` is escaped, line terminators are written as escapes).
//! Both are reproduced here so the compiled source and the fallback match the JavaScript output.
//!
//! The grammar implemented is the Annex B ("web reality") pattern grammar for a regular expression
//! without the `u` flag, which is what `new RegExp(source)` uses. It therefore works on UTF-16 code
//! units: astral characters count as two units, which is observable in character class ranges
//! (`[\u{1f600}-\u{1f601}]` written literally is an out-of-order range in JavaScript).

/// `RegExp.prototype.source` for a pattern the engine accepts.
pub fn source(pattern: &str) -> String {
    if pattern.is_empty() {
        return "(?:)".to_string();
    }

    let units: Vec<char> = pattern.chars().collect();
    let mut out = String::with_capacity(pattern.len());
    let mut in_class = false;
    let mut i = 0;
    while i < units.len() {
        let c = units[i];
        if c == '\\' && i + 1 < units.len() {
            let next = units[i + 1];
            out.push('\\');
            match line_terminator_escape(next) {
                Some(escape) => out.push_str(escape),
                None => out.push(next),
            }
            i += 2;
            continue;
        }
        match line_terminator_escape(c) {
            Some(escape) => {
                out.push('\\');
                out.push_str(escape);
            }
            None if c == '/' && !in_class => out.push_str("\\/"),
            None => {
                if c == '[' {
                    in_class = true;
                } else if c == ']' {
                    in_class = false;
                }
                out.push(c);
            }
        }
        i += 1;
    }
    out
}

fn line_terminator_escape(c: char) -> Option<&'static str> {
    match c {
        '\n' => Some("n"),
        '\r' => Some("r"),
        '\u{2028}' => Some("u2028"),
        '\u{2029}' => Some("u2029"),
        _ => None,
    }
}

/// Whether `new RegExp(pattern)` succeeds, i.e. does not throw a `SyntaxError`.
pub fn is_valid(pattern: &str) -> bool {
    Validator::new(pattern).validate().is_ok()
}

type Check = Result<(), ()>;

struct Validator {
    units: Vec<u16>,
    index: usize,
    group_names: Vec<String>,
    duplicate_name: bool,
}

impl Validator {
    fn new(pattern: &str) -> Self {
        let units: Vec<u16> = pattern.encode_utf16().collect();
        let (group_names, duplicate_name) = scan_group_names(&units);
        Self { units, index: 0, group_names, duplicate_name }
    }

    fn validate(&mut self) -> Check {
        if self.duplicate_name {
            return Err(());
        }
        self.disjunction()?;
        if self.index == self.units.len() {
            Ok(())
        } else {
            // An unmatched `)`.
            Err(())
        }
    }

    fn peek(&self) -> Option<u16> {
        self.units.get(self.index).copied()
    }

    fn at(&self, offset: usize) -> Option<u16> {
        self.units.get(self.index + offset).copied()
    }

    fn eat(&mut self, unit: u8) -> bool {
        if self.peek() == Some(u16::from(unit)) {
            self.index += 1;
            true
        } else {
            false
        }
    }

    fn starts_with(&self, prefix: &str) -> bool {
        prefix
            .bytes()
            .enumerate()
            .all(|(offset, byte)| self.at(offset) == Some(u16::from(byte)))
    }

    fn disjunction(&mut self) -> Check {
        loop {
            self.alternative()?;
            if !self.eat(b'|') {
                return Ok(());
            }
        }
    }

    fn alternative(&mut self) -> Check {
        loop {
            match self.peek() {
                None => return Ok(()),
                Some(unit) if unit == u16::from(b')') || unit == u16::from(b'|') => return Ok(()),
                _ => self.term()?,
            }
        }
    }

    fn term(&mut self) -> Check {
        // Assertions, which may not be quantified…
        if self.peek() == Some(u16::from(b'^')) || self.peek() == Some(u16::from(b'$')) {
            self.index += 1;
            return self.reject_quantifier();
        }
        if self.starts_with("\\b") || self.starts_with("\\B") {
            self.index += 2;
            return self.reject_quantifier();
        }
        if self.starts_with("(?<=") || self.starts_with("(?<!") {
            self.group()?;
            return self.reject_quantifier();
        }

        // …except for lookahead, which Annex B allows a quantifier on, like any other atom.
        if self.starts_with("(?=") || self.starts_with("(?!") {
            self.group()?;
        } else {
            self.atom()?;
        }
        if let Some(quantifier) = self.quantifier() {
            self.index = quantifier.end;
            if !quantifier.ordered {
                return Err(());
            }
            return self.reject_quantifier();
        }
        Ok(())
    }

    /// Fails if a quantifier follows, which has nothing to repeat.
    fn reject_quantifier(&mut self) -> Check {
        match self.quantifier() {
            Some(_) => Err(()),
            None => Ok(()),
        }
    }

    fn atom(&mut self) -> Check {
        let unit = match self.peek() {
            Some(unit) => unit,
            None => return Ok(()),
        };
        match u8::try_from(unit).ok() {
            Some(b'.') => {
                self.index += 1;
                Ok(())
            }
            Some(b'\\') => self.atom_escape(),
            Some(b'[') => self.character_class(),
            Some(b'(') => self.group(),
            Some(b')') => Err(()),
            Some(b'*') | Some(b'+') | Some(b'?') => Err(()),
            Some(b'{') => match self.quantifier() {
                // `{` only starts a quantifier when it parses as one; otherwise Annex B takes it,
                // and a stray `}` or `]`, as a literal character.
                Some(_) => Err(()),
                None => {
                    self.index += 1;
                    Ok(())
                }
            },
            _ => {
                self.index += 1;
                Ok(())
            }
        }
    }

    fn atom_escape(&mut self) -> Check {
        self.index += 1;
        let unit = match self.peek() {
            Some(unit) => unit,
            // A trailing `\`.
            None => return Err(()),
        };
        match u8::try_from(unit).ok() {
            Some(b'0'..=b'9') => {
                while matches!(self.peek().and_then(|u| u8::try_from(u).ok()), Some(b'0'..=b'9')) {
                    self.index += 1;
                }
                Ok(())
            }
            Some(b'c') => {
                if matches!(
                    self.at(1).and_then(|u| u8::try_from(u).ok()),
                    Some(b'a'..=b'z') | Some(b'A'..=b'Z')
                ) {
                    self.index += 2;
                }
                // Otherwise the `\` is a literal backslash and `c` is the next character.
                Ok(())
            }
            Some(b'k') if !self.group_names.is_empty() => {
                self.index += 1;
                let name = self.group_name().ok_or(())?;
                if self.group_names.contains(&name) {
                    Ok(())
                } else {
                    Err(())
                }
            }
            Some(b'x') => {
                self.index += 1;
                if self.hex_digits(2).is_some() {
                    self.index += 2;
                }
                Ok(())
            }
            Some(b'u') => {
                self.index += 1;
                if self.hex_digits(4).is_some() {
                    self.index += 4;
                }
                Ok(())
            }
            _ => {
                self.index += 1;
                Ok(())
            }
        }
    }

    fn group(&mut self) -> Check {
        self.index += 1;
        if self.eat(b'?') {
            match self.peek().and_then(|u| u8::try_from(u).ok()) {
                Some(b':') | Some(b'=') | Some(b'!') => self.index += 1,
                Some(b'<') => {
                    self.index += 1;
                    match self.peek().and_then(|u| u8::try_from(u).ok()) {
                        Some(b'=') | Some(b'!') => self.index += 1,
                        _ => {
                            self.group_name().ok_or(())?;
                        }
                    }
                }
                _ => return Err(()),
            }
        }
        self.disjunction()?;
        if self.eat(b')') {
            Ok(())
        } else {
            Err(())
        }
    }

    /// Consumes `<name>`, returning the name with its `\u` escapes resolved.
    fn group_name(&mut self) -> Option<String> {
        if !self.eat(b'<') {
            return None;
        }
        let mut name = String::new();
        loop {
            match self.peek() {
                None => return None,
                Some(unit) if unit == u16::from(b'>') => {
                    self.index += 1;
                    break;
                }
                Some(unit) if unit == u16::from(b'\\') => {
                    if self.at(1) != Some(u16::from(b'u')) {
                        return None;
                    }
                    self.index += 2;
                    let value = match self.hex_digits(4) {
                        Some(value) => {
                            self.index += 4;
                            value
                        }
                        None => {
                            if !self.eat(b'{') {
                                return None;
                            }
                            let start = self.index;
                            let mut value: u32 = 0;
                            while let Some(digit) =
                                self.peek().and_then(|u| char::from_u32(u32::from(u)))
                            {
                                match digit.to_digit(16) {
                                    Some(digit) => {
                                        value = value.checked_mul(16)?.checked_add(digit)?;
                                        self.index += 1;
                                    }
                                    None => break,
                                }
                            }
                            if self.index == start || !self.eat(b'}') || value > 0x10_ffff {
                                return None;
                            }
                            value
                        }
                    };
                    name.push(char::from_u32(value)?);
                }
                Some(unit) => {
                    self.index += 1;
                    let mut buffer = [unit, 0];
                    let len = if is_leading_surrogate(unit) {
                        match self.peek() {
                            Some(low) if is_trailing_surrogate(low) => {
                                self.index += 1;
                                buffer[1] = low;
                                2
                            }
                            _ => 1,
                        }
                    } else {
                        1
                    };
                    let decoded = String::from_utf16(&buffer[..len]).ok()?;
                    name.push_str(&decoded);
                }
            }
        }
        if is_identifier_name(&name) {
            Some(name)
        } else {
            None
        }
    }

    fn character_class(&mut self) -> Check {
        self.index += 1;
        self.eat(b'^');
        loop {
            match self.peek() {
                // An unterminated class.
                None => return Err(()),
                Some(unit) if unit == u16::from(b']') => {
                    self.index += 1;
                    return Ok(());
                }
                _ => {}
            }
            let left = self.class_atom()?;
            if self.peek() == Some(u16::from(b'-'))
                && self.at(1).is_some()
                && self.at(1) != Some(u16::from(b']'))
            {
                self.index += 1;
                let right = self.class_atom()?;
                // Annex B allows a class escape (`\d`, `\w`, …) as a bound, which is then a
                // literal `-` between two class escapes rather than a range.
                if let (Some(left), Some(right)) = (left, right) {
                    if left > right {
                        return Err(());
                    }
                }
            }
        }
    }

    /// Consumes one class atom, returning its code unit value unless it is a class escape.
    fn class_atom(&mut self) -> Result<Option<u32>, ()> {
        let unit = self.peek().ok_or(())?;
        if unit != u16::from(b'\\') {
            self.index += 1;
            return Ok(Some(u32::from(unit)));
        }
        self.index += 1;
        let escape = self.peek().ok_or(())?;
        let value = match u8::try_from(escape).ok() {
            Some(b'd') | Some(b'D') | Some(b's') | Some(b'S') | Some(b'w') | Some(b'W') => {
                self.index += 1;
                return Ok(None);
            }
            Some(b'b') => {
                self.index += 1;
                0x08
            }
            Some(b'n') => {
                self.index += 1;
                0x0a
            }
            Some(b'r') => {
                self.index += 1;
                0x0d
            }
            Some(b't') => {
                self.index += 1;
                0x09
            }
            Some(b'v') => {
                self.index += 1;
                0x0b
            }
            Some(b'f') => {
                self.index += 1;
                0x0c
            }
            Some(b'c') => {
                match self.at(1).and_then(|u| u8::try_from(u).ok()) {
                    Some(letter @ (b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'_')) => {
                        self.index += 2;
                        u32::from(letter % 32)
                    }
                    // A literal backslash; `c` is the following class atom.
                    _ => u32::from(b'\\'),
                }
            }
            Some(b'k') if !self.group_names.is_empty() => return Err(()),
            Some(b'x') => {
                self.index += 1;
                match self.hex_digits(2) {
                    Some(value) => {
                        self.index += 2;
                        value
                    }
                    None => u32::from(b'x'),
                }
            }
            Some(b'u') => {
                self.index += 1;
                match self.hex_digits(4) {
                    Some(value) => {
                        self.index += 4;
                        value
                    }
                    None => u32::from(b'u'),
                }
            }
            Some(digit @ b'0'..=b'9') => self.legacy_octal(digit),
            _ => {
                self.index += 1;
                u32::from(escape)
            }
        };
        Ok(Some(value))
    }

    /// `LegacyOctalEscapeSequence`, which also covers `\8` and `\9` as identity escapes.
    fn legacy_octal(&mut self, first: u8) -> u32 {
        if first > b'7' {
            self.index += 1;
            return u32::from(first);
        }
        let mut value: u32 = 0;
        let mut digits = 0;
        while digits < 3 {
            let digit = match self.peek().and_then(|u| u8::try_from(u).ok()) {
                Some(digit @ b'0'..=b'7') => u32::from(digit - b'0'),
                _ => break,
            };
            let next = value * 8 + digit;
            if next > 0xff {
                break;
            }
            value = next;
            digits += 1;
            self.index += 1;
        }
        value
    }

    fn hex_digits(&self, count: usize) -> Option<u32> {
        let mut value: u32 = 0;
        for offset in 1..=count {
            let unit = self.at(offset)?;
            let digit = char::from_u32(u32::from(unit))?.to_digit(16)?;
            value = value * 16 + digit;
        }
        Some(value)
    }

    fn quantifier(&self) -> Option<Quantifier> {
        let unit = u8::try_from(self.peek()?).ok()?;
        let mut end = match unit {
            b'*' | b'+' | b'?' => self.index + 1,
            b'{' => return self.braced_quantifier(),
            _ => return None,
        };
        if self.units.get(end) == Some(&u16::from(b'?')) {
            end += 1;
        }
        Some(Quantifier { end, ordered: true })
    }

    fn braced_quantifier(&self) -> Option<Quantifier> {
        let mut offset = 1;
        let min = self.decimal_digits(&mut offset)?;
        let mut max = None;
        if self.at(offset) == Some(u16::from(b',')) {
            offset += 1;
            if self.at(offset) != Some(u16::from(b'}')) {
                max = Some(self.decimal_digits(&mut offset)?);
            }
        }
        if self.at(offset) != Some(u16::from(b'}')) {
            return None;
        }
        offset += 1;
        if self.at(offset) == Some(u16::from(b'?')) {
            offset += 1;
        }
        let ordered = match &max {
            Some(max) => compare_decimals(&min, max) != std::cmp::Ordering::Greater,
            None => true,
        };
        Some(Quantifier { end: self.index + offset, ordered })
    }

    fn decimal_digits(&self, offset: &mut usize) -> Option<String> {
        let mut digits = String::new();
        while let Some(digit) = self.at(*offset).and_then(|u| u8::try_from(u).ok()) {
            if !digit.is_ascii_digit() {
                break;
            }
            digits.push(char::from(digit));
            *offset += 1;
        }
        if digits.is_empty() {
            None
        } else {
            Some(digits)
        }
    }
}

struct Quantifier {
    end: usize,
    /// `false` for `{n,m}` with `n > m`, which is a `SyntaxError` rather than a literal.
    ordered: bool,
}

fn compare_decimals(left: &str, right: &str) -> std::cmp::Ordering {
    let left = left.trim_start_matches('0');
    let right = right.trim_start_matches('0');
    left.len().cmp(&right.len()).then_with(|| left.cmp(right))
}

/// Collects the `(?<name>` group names, and whether any is a duplicate, skipping character classes.
fn scan_group_names(units: &[u16]) -> (Vec<String>, bool) {
    let mut names = Vec::new();
    let mut duplicate = false;
    let mut in_class = false;
    let mut index = 0;
    while index < units.len() {
        let unit = units[index];
        match u8::try_from(unit).ok() {
            Some(b'\\') => {
                index += 2;
                continue;
            }
            Some(b'[') if !in_class => in_class = true,
            Some(b']') if in_class => in_class = false,
            Some(b'(') if !in_class => {
                let is_named = units.get(index + 1) == Some(&u16::from(b'?'))
                    && units.get(index + 2) == Some(&u16::from(b'<'))
                    && !matches!(
                        units.get(index + 3).and_then(|u| u8::try_from(*u).ok()),
                        Some(b'=') | Some(b'!')
                    );
                if is_named {
                    let mut scan = Validator {
                        units: units.to_vec(),
                        index: index + 3,
                        group_names: Vec::new(),
                        duplicate_name: false,
                    };
                    if let Some(name) = scan.group_name() {
                        if names.contains(&name) {
                            duplicate = true;
                        }
                        names.push(name);
                    } else {
                        // An invalid name; the group name grammar is re-checked while parsing.
                        names.push(String::new());
                    }
                    index = scan.index;
                    continue;
                }
            }
            _ => {}
        }
        index += 1;
    }
    (names, duplicate)
}

/// `RegExpIdentifierName`, approximating `ID_Start`/`ID_Continue` with Unicode alphanumerics.
fn is_identifier_name(name: &str) -> bool {
    let mut chars = name.chars();
    let start = match chars.next() {
        Some(start) => start,
        None => return false,
    };
    let is_start = start == '$' || start == '_' || start.is_alphabetic();
    is_start
        && chars.all(|c| {
            c == '$' || c == '_' || c.is_alphanumeric() || c == '\u{200c}' || c == '\u{200d}'
        })
}
"}

