//! `/tmp/globcheck/validfuzz.js`): for each pattern, either `null` (a `SyntaxError`) or the
//! `RegExp.prototype.source` of the compiled expression.

use std::collections::BTreeMap;

#[test]
fn validity_and_source_match_v8() {
    let raw = match std::fs::read_to_string("/tmp/globcheck/valid.json") {
        Ok(raw) => raw,
        Err(_) => return,
    };
    let map: BTreeMap<String, Option<String>> = serde_json::from_str(&raw).unwrap();
    let mut failures = Vec::new();
    for (pattern, expected) in &map {
        let valid = jscodeshift_core::glob::jsregex::is_valid(pattern);
        if valid != expected.is_some() {
            failures.push(format!(
                "{pattern:?}: js valid={} rs valid={valid}",
                expected.is_some()
            ));
            continue;
        }
        if let Some(expected) = expected {
            let actual = jscodeshift_core::glob::jsregex::source(pattern);
            if &actual != expected {
                failures.push(format!("{pattern:?}: js {expected:?} rs {actual:?}"));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} failures:\n{}",
        failures.len(),
        map.len(),
        failures.iter().take(60).cloned().collect::<Vec<_>>().join("\n")
    );
}
"}

