{"command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/value.rs","file_text":"//! A JavaScript value model.
//!
//! Option values flow from the command line into the transform options object, so they have to keep
//! JavaScript's distinctions: `NaN` (produced by `Number('abc')`), `undefined` vs `null`, and the
//! `JSON.parse` result shapes that unknown options are parsed into.

use std::collections::BTreeMap;
use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub enum Value {
    Undefined,
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

impl Value {
    pub fn string(value: impl Into<String>) -> Self {
        Value::String(value.into())
    }

    pub fn is_undefined(&self) -> bool {
        matches!(self, Value::Undefined)
    }

    pub fn as_bool_strict(&self) -> Option<bool> {
        match self {
            Value::Bool(value) => Some(*value),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(value) => Some(value),
            _ => None,
        }
    }

    pub fn as_number(&self) -> Option<f64> {
        match self {
            Value::Number(value) => Some(*value),
            _ => None,
        }
    }

    pub fn as_array(&self) -> Option<&[Value]> {
        match self {
            Value::Array(values) => Some(values),
            _ => None,
        }
    }

    /// JavaScript's `===`.
    pub fn strict_equals(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Undefined, Value::Undefined) => true,
            (Value::Null, Value::Null) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            // `NaN === NaN` is false.
            (Value::Number(a), Value::Number(b)) => a == b,
            (Value::String(a), Value::String(b)) => a == b,
            // Objects and arrays compare by identity; values reaching here were built separately.
            _ => false,
        }
    }

    /// `String(value)`, used for help text and error messages.
    pub fn to_js_string(&self) -> String {
        match self {
            Value::Undefined => "undefined".to_string(),
            Value::Null => "null".to_string(),
            Value::Bool(value) => value.to_string(),
            Value::Number(value) => number_to_string(*value),
            Value::String(value) => value.clone(),
            Value::Array(values) => {
                values.iter().map(|value| value.to_js_string()).collect::<Vec<_>>().join(",")
            }
            Value::Object(_) => "[object Object]".to_string(),
        }
    }

    /// `JSON.parse(input)`, returning `None` when the parse throws.
    pub fn parse_json(input: &str) -> Option<Value> {
        let parsed: serde_json::Value = serde_json::from_str(input).ok()?;
        Some(Value::from_json(parsed))
    }

    pub fn from_json(value: serde_json::Value) -> Value {
        match value {
            serde_json::Value::Null => Value::Null,
            serde_json::Value::Bool(value) => Value::Bool(value),
            serde_json::Value::Number(value) => Value::Number(value.as_f64().unwrap_or(f64::NAN)),
            serde_json::Value::String(value) => Value::String(value),
            serde_json::Value::Array(values) => {
                Value::Array(values.into_iter().map(Value::from_json).collect())
            }
            serde_json::Value::Object(entries) => Value::Object(
                entries.into_iter().map(|(key, value)| (key, Value::from_json(value))).collect(),
            ),
        }
    }

    /// `Number(value)` for the string values the command line produces.
    pub fn to_number(input: &str) -> f64 {
        let trimmed = input.trim_matches(|c: char| {
            c.is_whitespace() || c == '\u{feff}' || c == '\u{2028}' || c == '\u{2029}'
        });
        if trimmed.is_empty() {
            return 0.0;
        }
        if let Some(hex) = trimmed.strip_prefix("0x").or_else(|| trimmed.strip_prefix("0X")) {
            return i64::from_str_radix(hex, 16).map(|v| v as f64).unwrap_or(f64::NAN);
        }
        if let Some(octal) = trimmed.strip_prefix("0o").or_else(|| trimmed.strip_prefix("0O")) {
            return i64::from_str_radix(octal, 8).map(|v| v as f64).unwrap_or(f64::NAN);
        }
        if let Some(binary) = trimmed.strip_prefix("0b").or_else(|| trimmed.strip_prefix("0B")) {
            return i64::from_str_radix(binary, 2).map(|v| v as f64).unwrap_or(f64::NAN);
        }
        match trimmed {
            "Infinity" | "+Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            _ => trimmed.parse::<f64>().unwrap_or(f64::NAN),
        }
    }

    /// The serialization used for the worker protocol and for `options` handed to a transform.
    pub fn to_json(&self) -> serde_json::Value {
        match self {
            // `JSON.stringify` drops `undefined`; the protocol encodes it as null and the receiving
            // side never reads an undefined option (they are absent from the parse result).
            Value::Undefined | Value::Null => serde_json::Value::Null,
            Value::Bool(value) => serde_json::Value::Bool(*value),
            Value::Number(value) => serde_json::Number::from_f64(*value)
                .map(serde_json::Value::Number)
                .unwrap_or(serde_json::Value::Null),
            Value::String(value) => serde_json::Value::String(value.clone()),
            Value::Array(values) => {
                serde_json::Value::Array(values.iter().map(Value::to_json).collect())
            }
            Value::Object(entries) => serde_json::Value::Object(
                entries.iter().map(|(key, value)| (key.clone(), value.to_json())).collect(),
            ),
        }
    }
}

/// An insertion-ordered string map, matching the iteration order of a JavaScript object.
#[derive(Clone, Debug, Default)]
pub struct ValueMap {
    keys: Vec<String>,
    values: BTreeMap<String, Value>,
}

impl ValueMap {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn contains_key(&self, key: &str) -> bool {
        self.values.contains_key(key)
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.values.get(key)
    }

    pub fn insert(&mut self, key: impl Into<String>, value: Value) {
        let key = key.into();
        if !self.values.contains_key(&key) {
            self.keys.push(key.clone());
        }
        self.values.insert(key, value);
    }

    pub fn keys(&self) -> impl Iterator<Item = &String> {
        self.keys.iter()
    }

    pub fn iter(&self) -> impl Iterator<Item = (&String, &Value)> {
        self.keys.iter().map(move |key| (key, &self.values[key]))
    }

    pub fn push_to_list(&mut self, key: &str, value: Value) {
        match self.values.get_mut(key) {
            Some(Value::Array(values)) => values.push(value),
            _ => self.insert(key.to_string(), Value::Array(vec![value])),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::Value::Object(
            self.iter().map(|(key, value)| (key.clone(), value.to_json())).collect(),
        )
    }

    pub fn from_json(value: &serde_json::Value) -> Self {
        let mut map = ValueMap::new();
        if let serde_json::Value::Object(entries) = value {
            for (key, value) in entries {
                map.insert(key.clone(), Value::from_json(value.clone()));
            }
        }
        map
    }
}

/// `String(number)`.
pub fn number_to_string(value: f64) -> String {
    if value.is_nan() {
        return "NaN".to_string();
    }
    if value.is_infinite() {
        return if value > 0.0 { "Infinity".to_string() } else { "-Infinity".to_string() };
    }
    if value == 0.0 {
        return "0".to_string();
    }
    if value.fract() == 0.0 && value.abs() < 1e21 {
        let mut out = String::new();
        let _ = write!(out, "{}", value as i64);
        return out;
    }
    let mut out = String::new();
    let _ = write!(out, "{value}");
    out
}
