/// The error `throwError` raises: a message and the exit code the CLI should use.
#[derive(Clone, Debug)]
pub struct ParseError {
    pub exit_code: i32,
    pub message: String,
}

impl ParseError {
    fn new(exit_code: i32, message: String, help_text: Option<&str>) -> Self {
        let message = match help_text {
            Some(help) => format!("{message}\n\n---\n\n{help}"),
            None => message,
        };
        ParseError { exit_code, message }
    }
}

#[derive(Clone, Debug)]
pub struct ParseResult {
    pub positional_arguments: Vec<Value>,
    pub options: ValueMap,
}

/// The option table, in declaration order (the order `for...in` visits it).
#[derive(Clone, Debug, Default)]
pub struct Options {
    specs: Vec<OptionSpec>,
}

impl Options {
    pub fn new(specs: Vec<OptionSpec>) -> Self {
        let mut options = Options { specs };
        // `prepareOptions` appends `help` to the caller's table, and it is appended before parsing
        // so `--help` is always available; the table is shared, hence it is added once here.
        options.specs.push(
            OptionSpec::new("help")
                .display_index(5)
                .abbr('h')
                .help("print this help and exit")
                .callback(Callback::Help),
        );
        options
    }

    fn find(&self, key: &str) -> Option<&OptionSpec> {
        self.specs.iter().find(|spec| spec.key == key)
    }

    /// `prepareOptions`: the flag-name to option lookup table.
    fn prepared(&self) -> Vec<(String, &OptionSpec)> {
        let mut prepared = Vec::new();
        for spec in &self.specs {
            prepared.push((format!("--{}", spec.full), spec));
            if let Some(abbr) = spec.abbr {
                prepared.push((format!("-{abbr}"), spec));
            }
            if spec.flag {
                prepared.push((format!("--no-{}", spec.full), spec));
            }
        }
        prepared
    }

    pub fn get_help_text(&self) -> String {
        let mut specs: Vec<&OptionSpec> = self.specs.iter().collect();
        // `Array.prototype.sort` is stable, and the comparator only orders by `display_index`.
        specs.sort_by_key(|spec| spec.display_index);
        let formatted: Vec<String> = specs.iter().map(|spec| format_option(spec)).collect();

        let text = format!(
            "
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{}
",
            formatted.join("\n")
        );
        // `String.prototype.trimLeft`
        text.trim_start_matches(is_js_whitespace).to_string()
    }

    pub fn parse(
        &self,
        args: &[String],
        hooks: &dyn ParseHooks,
    ) -> Result<ParseResult, ParseError> {
        parse(self, args, hooks)
    }
}

/// Side effects `process` and `callback` hooks need: reading a file, and the version banner.
pub trait ParseHooks {
    /// `JSON.parse(fs.readFileSync(file))`, or the error message it throws.
    fn read_json_file(&self, path: &str) -> Result<Value, String>;
    /// The text of the `--version` callback.
    fn version_text(&self) -> String;
}

fn is_js_whitespace(c: char) -> bool {
    c.is_whitespace() || c == '\u{feff}'
}

/// `formatOption`
fn format_option(option: &OptionSpec) -> String {
    let mut text = String::from("  ");
    match option.abbr {
        Some(abbr) => {
            text.push('-');
            text.push(abbr);
            text.push_str(", ");
        }
        None => text.push_str("    "),
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(&option.full);
    if let Some(choices) = &option.choices {
        text.push('=');
        text.push_str(
            &choices.iter().map(|choice| choice.to_js_string()).collect::<Vec<_>>().join("|"),
        );
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }

    let has_default = option.default_help.is_some() || !option.default.is_undefined();
    if has_default || option.help.is_some() {
        text.push_str("  ");
        // `text.length` counts UTF-16 code units; the help table is ASCII.
        let length = text.chars().count();
        if length < 32 {
            text.push_str(&" ".repeat(32 - length));
        }
        let text_length = text.chars().count();
        if let Some(help) = &option.help {
            text.push_str(help);
        }
        if has_default {
            if option.help.is_some() {
                text.push('\n');
            }
            let default = match &option.default_help {
                Some(default_help) => default_help.clone(),
                None => option.default.to_js_string(),
            };
            text.push_str(&format!("{}(default: {default})", " ".repeat(text_length)));
        }
    }

    text
}

/// `validateOptions`
fn validate_options(
    parsed_options: &ValueMap,
    options: &Options,
    help_text: &str,
) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for spec in &options.specs {
        if let Some(choices) = &spec.choices {
            let value = parsed_options.get(&spec.key).cloned().unwrap_or(Value::Undefined);
            if !choices.iter().any(|choice| includes(choice, &value)) {
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    spec.full,
                    choices.iter().map(|c| c.to_js_string()).collect::<Vec<_>>().join(",")
                ));
            }
        }
    }
    if !errors.is_empty() {
        return Err(ParseError::new(1, errors.join("\n"), Some(help_text)));
    }
    Ok(())
}

/// `Array.prototype.includes` comparison (SameValueZero, so `NaN` matches `NaN`).
fn includes(choice: &Value, value: &Value) -> bool {
    match (choice, value) {
        (Value::Number(a), Value::Number(b)) if a.is_nan() && b.is_nan() => true,
        _ => choice.strict_equals(value),
    }
}

/// `isOption`: `/^--?/.test(value)`
fn is_option(value: Option<&String>) -> bool {
    match value {
        Some(value) => value.starts_with('-'),
        // `/^--?/.test(undefined)` tests the string "undefined".
        None => false,
    }
}

/// The unknown-option `process` hook: `JSON.parse` with the raw string as fallback.
fn process_unknown(value: &str) -> Value {
    Value::parse_json(value).unwrap_or_else(|| Value::string(value))
}

fn apply_process(
    process: Process,
    value: &str,
    hooks: &dyn ParseHooks,
) -> Result<Value, ParseError> {
    Ok(match process {
        Process::Number => Value::Number(Value::to_number(value)),
        Process::JsonOrString => process_unknown(value),
        Process::ParseJsonFile => match hooks.read_json_file(value) {
            Ok(value) => value,
            // An uncaught throw from `process` propagates out of `parse`; `bin/jscodeshift.js`
            // catches it and, having no `exitCode`, exits with 1 and writes the bare message.
            Err(message) => return Err(ParseError { exit_code: 1, message }),
        },
    })
}

/// The shape of an option resolved for one argument: either a known spec or a synthesized one.
struct ResolvedOption {
    key: String,
    full: String,
    flag: bool,
    list: bool,
    callback: Option<Callback>,
    process: Option<Process>,
}

fn parse(
    options: &Options,
    args: &[String],
    hooks: &dyn ParseHooks,
) -> Result<ParseResult, ParseError> {
    let prepared = options.prepared();

    let mut parsed_options = ValueMap::new();
    // Tracks the `missingValue` sentinel, which is a Symbol in the original and so cannot collide
    // with any real option value.
    let mut missing_value: Vec<String> = Vec::new();
    let mut positional_arguments = Vec::new();

    for spec in &options.specs {
        if !spec.default.is_undefined() {
            parsed_options.insert(spec.key.clone(), spec.default.clone());
        } else if spec.list {
            parsed_options.insert(spec.key.clone(), Value::Array(Vec::new()));
        }
    }

