    while i < args.len() {
        let arg = &args[i];
        if !is_option(Some(arg)) {
            positional_arguments.push(if is_all_digits(arg) {
                Value::Number(Value::to_number(arg))
            } else {
                Value::string(arg.clone())
            });
            i += 1;
            continue;
        }

        let mut option_name = arg.clone();
        let mut value: Option<String> = None;
        if let Some(index) = arg.find('=') {
            option_name = arg[..index].to_string();
            value = Some(arg[index + 1..].to_string());
        }

        let option = match prepared.iter().find(|(name, _)| *name == option_name) {
            Some((_, spec)) => ResolvedOption {
                key: spec.key.clone(),
                full: spec.full.clone(),
                flag: spec.flag,
                list: spec.list,
                callback: spec.callback,
                process: spec.process,
            },
            None => {
                // Unknown options are just "passed along".
                let real_option_name = strip_option_prefix(&option_name);
                let is_list = parsed_options.contains_key(&real_option_name)
                    && parsed_options.get(&real_option_name).map(|v| v.as_bool_strict())
                        != Some(Some(true));
                let resolved = ResolvedOption {
                    flag: !parsed_options.contains_key(&real_option_name)
                        && value.is_none()
                        && is_option(args.get(i + 1)),
                    key: real_option_name.clone(),
                    full: real_option_name.clone(),
                    list: is_list,
                    callback: None,
                    process: Some(Process::JsonOrString),
                };

                if is_list {
                    let current = parsed_options.get(&real_option_name).cloned();
                    if !matches!(current, Some(Value::Array(_))) {
                        let replacement = match current {
                            Some(Value::Bool(true)) => Value::Array(Vec::new()),
                            Some(current) => Value::Array(vec![current]),
                            None => Value::Array(vec![Value::Undefined]),
                        };
                        parsed_options.insert(real_option_name.clone(), replacement);
                    }
                }

                resolved
            }
        };

        if let Some(callback) = option.callback {
            let message = match callback {
                Callback::Help => options.get_help_text(),
                Callback::Version => hooks.version_text(),
            };
            return Err(ParseError::new(0, message, None));
        } else if option.flag {
            let value = if option_name.starts_with("--no-") {
                Value::Bool(false)
            } else if let Some(value) = value {
                Value::Bool(value == "1")
            } else {
                Value::Bool(true)
            };
            missing_value.retain(|key| key != &option.key);
            parsed_options.insert(option.key.clone(), value);
        } else {
            if value.is_none() && i < args.len() - 1 && !is_option(args.get(i + 1)) {
                value = Some(args[i + 1].clone());
                i += 1;
            }
            match value {
                Some(value) => {
                    let value = match option.process {
                        Some(process) => apply_process(process, &value, hooks)?,
                        None => Value::string(value),
                    };
                    missing_value.retain(|key| key != &option.key);
                    if option.list {
                        parsed_options.push_to_list(&option.key, value);
                    } else {
                        parsed_options.insert(option.key.clone(), value);
                    }
                }
                None => {
                    if !parsed_options.contains_key(&option.key) {
                        parsed_options.insert(option.key.clone(), Value::Undefined);
                    }
                    if !missing_value.contains(&option.key) {
                        missing_value.push(option.key.clone());
                    }
                }
            }
        }

        i += 1;
    }

    let help_text = options.get_help_text();
    if let Some(key) = parsed_options.keys().find(|key| missing_value.contains(key)) {
        // The original reads `options[optionName].full`; for an unknown option that lookup is
        // `undefined`, so the property access throws a TypeError with no exit code.
        let Some(spec) = options.find(key) else {
            return Err(ParseError {
                exit_code: 1,
                message: "Cannot read properties of undefined (reading 'full')".to_string(),
            });
        };
        return Err(ParseError::new(
            1,
            format!("Missing value: --{} requires a value", spec.full),
            Some(&help_text),
        ));
    }

    // `missingValue` placeholders are gone by now; drop the sentinel slots that were never filled.
    validate_options(&parsed_options, options, &help_text)?;

    Ok(ParseResult { positional_arguments, options: parsed_options })
}

/// `optionName.replace(/^--?(no-)?/, '')`
fn strip_option_prefix(option_name: &str) -> String {
    let rest = match option_name.strip_prefix("--") {
        Some(rest) => rest,
        None => option_name.strip_prefix('-').unwrap_or(option_name),
    };
    rest.strip_prefix("no-").unwrap_or(rest).to_string()
}

/// `/^\d+$/.test(arg)`
fn is_all_digits(arg: &str) -> bool {
    !arg.is_empty() && arg.chars().all(|c| c.is_ascii_digit())
}

/// `String(value)` for a parsed option value, used when options are echoed back.
pub fn value_to_string(value: &Value) -> String {
    match value {
        Value::Number(number) => number_to_string(*number),
        other => other.to_js_string(),
    }
}
