    }

    /// `array.push(value)`, where a non-array value makes the property access throw.
    pub fn push_to_list(&mut self, key: &str, value: Value) -> Result<(), String> {
        match self.values.get_mut(key) {
            Some(Value::Array(values)) => {
                values.push(value);
                Ok(())
            }
            _ => Err(format!("parsedOptions[option.key].push is not a function")),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::Value::Object(
            self.iter()
