                .filter(|(_, value)| !value.is_undefined() && !value.is_missing_value())
                .map(|(key, value)| (key.clone(), value.to_json()))
                .collect(),
        )
    }

    pub fn from_json(value: &serde_json::Value) -> Self {
        let mut map = ValueMap::new();
        if let serde_json::Value::Object(entries) = value {
            for (key, value) in entries {
                map.insert(key.clone(), Value::from_json(value.clone()));
            }
        }
        map
    }
}

/// Whether a property key is an array index, i.e. its canonical numeric string form.
fn array_index(key: &str) -> Option<u32> {
    if key == "0" {
        return Some(0);
    }
    if key.is_empty() || key.starts_with('0') || !key.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    // Array indices stop below 2^32 - 1; larger numeric keys are ordinary string keys.
    key.parse::<u32>().ok().filter(|index| *index != u32::MAX)
}"}

