use std::env;
use std::ffi::c_int;

/// `picocolors`' `isColorSupported`, evaluated once per process as in the original module.
pub fn is_color_supported() -> bool {
    static SUPPORTED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *SUPPORTED.get_or_init(|| {
        let argv: Vec<String> = env::args().skip(1).collect();
        if env::var_os("NO_COLOR").is_some() || argv.iter().any(|arg| arg == "--no-color") {
            return false;
        }
        env::var_os("FORCE_COLOR").is_some()
            || argv.iter().any(|arg| arg == "--color")
            || cfg!(windows)
            || (is_stdout_tty() && env::var("TERM").ok().as_deref() != Some("dumb"))
            || env::var_os("CI").is_some()
    })
}

fn is_stdout_tty() -> bool {
    extern "C" {
        fn isatty(fd: c_int) -> c_int;
    }
    // SAFETY: `isatty` only inspects the descriptor.
    unsafe { isatty(1) == 1 }
}

/// A `picocolors` formatter: the open/close escapes plus the replacement for a nested close.
struct Formatter {
    open: &'static str,
    close: &'static str,
    replace: &'static str,
}

impl Formatter {
    const fn new(open: &'static str, close: &'static str) -> Self {
        Formatter { open, close, replace: open }
    }

    fn apply(&self, input: &str) -> String {
        if !is_color_supported() {
            return input.to_string();
        }
        match input[self.open.len().min(input.len())..].find(self.close) {
            Some(offset) => {
                let index = self.open.len().min(input.len()) + offset;
                format!("{}{}{}", self.open, self.replace_close(input, index), self.close)
            }
            None => format!("{}{}{}", self.open, input, self.close),
        }
    }

    /// `replaceClose`: every nested close escape is swapped for `replace`.
    fn replace_close(&self, input: &str, mut index: usize) -> String {
        let mut result = String::new();
        let mut cursor = 0;
        loop {
            result.push_str(&input[cursor..index]);
            result.push_str(self.replace);
            cursor = index + self.close.len();
            match input[cursor..].find(self.close) {
                Some(offset) => index = cursor + offset,
                None => break,
            }
        }
        result.push_str(&input[cursor..]);
        result
    }
}

macro_rules! color {
    ($name:ident, $open:expr, $close:expr) => {
        pub fn $name(input: &str) -> String {
            Formatter::new($open, $close).apply(input)
        }
    };
}

