use std::fs;

use crate::glob::{self, Options};

/// The module-level `matchers` array of the original.
#[derive(Clone, Debug, Default)]
pub struct IgnoreFiles {
    matchers: Vec<String>,
}

impl IgnoreFiles {
    pub fn new() -> Self {
        Self::default()
    }

    /// `addIgnorePattern`: approximates gitignore patterns with globs.
    fn add_ignore_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.matchers.push(format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            self.matchers.push(format!("**/{pattern}**"));
            self.matchers.push(format!("{pattern}**"));
        }
        self.matchers.push(pattern.to_string());
    }

    /// `addIgnoreFromInput`
    pub fn add(&mut self, patterns: &[String]) {
        for pattern in patterns {
            self.add_ignore_pattern(pattern);
        }
    }

    /// `addIgnoreFromFile`. `fs.statSync` throws for a missing path, which propagates.
    pub fn add_from_file(&mut self, files: &[String]) -> Result<(), std::io::Error> {
        let mut lines: Vec<String> = Vec::new();
        for config in files {
            let stats = fs::metadata(config)?;
            if stats.is_file() {
                let content = read_to_string_lossy(config)?;
                lines.extend(split_lines(&content));
            }
        }
        for line in &lines {
            self.add_ignore_pattern(line);
        }
        Ok(())
    }

    /// `shouldIgnore`
    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        // Files discovered from a relative source path (e.g. `../src` or `./src`) are enumerated
        // with a leading `../` or `./` traversal prefix, which picomatch's `**` does not match
        // across, so the path is also tested with that prefix stripped.
        // See https://github.com/facebook/jscodeshift/issues/556
        let normalized_path = strip_traversal_prefix(path);
        self.is_match(path) || (normalized_path != path && self.is_match(&normalized_path))
    }

    fn is_match(&self, path: &str) -> bool {
        let options = Options { dot: true, ..Options::default() };
        self.matchers.iter().any(|pattern| glob::is_match(path, pattern, options))
    }
}

/// `path.replace(/^(?:\.\.?[/\\])+/, '')`
fn strip_traversal_prefix(path: &str) -> String {
    let bytes = path.as_bytes();
    let mut i = 0;
    loop {
        let rest = &bytes[i..];
        let len = if rest.starts_with(b"../") || rest.starts_with(b"..\\") {
            3
        } else if rest.starts_with(b"./") || rest.starts_with(b".\\") {
            2
        } else {
            break;
        };
        i += len;
    }
    path[i..].to_string()
}

/// `content.split(/\r?\n/)`
fn split_lines(content: &str) -> Vec<String> {
    content.split('\n').map(|line| line.strip_suffix('\r').unwrap_or(line).to_string()).collect()
}

/// `fs.readFileSync(file, 'utf8')`, which replaces invalid sequences rather than failing.
fn read_to_string_lossy(path: &str) -> Result<String, std::io::Error> {
    Ok(String::from_utf8_lossy(&fs::read(path)?).into_owned())
}
