/// `[].concat(input)` for a missing, single or array input.
fn concat(input: &Value) -> Vec<Value> {
    match input {
        Value::Array(items) => items.clone(),
        Value::Undefined | Value::Null | Value::Bool(false) => Vec::new(),
        Value::String(value) if value.is_empty() => Vec::new(),
        Value::Number(value) if *value == 0.0 || value.is_nan() => Vec::new(),
        value => vec![value.clone()],
    }
}

/// `path.replace(/^(?:\.\.?[/\\])+/, '')`
fn strip_traversal_prefix(path: &str) -> String {
    let bytes = path.as_bytes();
    let mut index = 0;
    loop {
        let rest = &bytes[index..];
        let length = if rest.starts_with(b"../") || rest.starts_with(b"..\\") {
            3
        } else if rest.starts_with(b"./") || rest.starts_with(b".\\") {
            2
        } else {
            break;
        };
        index += length;
    }
    path[index..].to_string()
}

/// `content.split(/\r?\n/)`
fn split_lines(content: &str) -> Vec<String> {
    content.split('\n').map(|line| line.strip_suffix('\r').unwrap_or(line).to_string()).collect()
}

/// `fs.readFileSync(file, 'utf8')`, which replaces invalid sequences rather than failing.
fn read_to_string_lossy(path: &str) -> Result<String, std::io::Error> {
    Ok(String::from_utf8_lossy(&fs::read(path)?).into_owned())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn with_patterns(patterns: &[&str]) -> IgnoreFiles {
        let mut ignores = IgnoreFiles::new();
        for pattern in patterns {
            ignores.add(&Value::string(*pattern));
        }
        ignores
    }

    #[test]
    fn ignores_nothing_without_patterns() {
        assert!(!IgnoreFiles::new().should_ignore("src/node_modules/foo.js"));
    }

    #[test]
    fn matches_glob_patterns_with_and_without_traversal_prefix() {
        let ignores = with_patterns(&["**/node_modules/**"]);
        assert!(ignores.should_ignore("src/node_modules/foo.js"));
        assert!(ignores.should_ignore("/abs/src/node_modules/foo.js"));
        assert!(ignores.should_ignore("../company.reactapp/src/node_modules/foo.js"));
        assert!(ignores.should_ignore("./src/node_modules/foo.js"));
        assert!(ignores.should_ignore("../node_modules/foo.js"));
        assert!(ignores.should_ignore("../../a/b/node_modules/x.js"));
        assert!(!ignores.should_ignore("../src/app.js"));
    }

    #[test]
    fn matches_bare_directory_names_and_file_globs() {
        let ignores = with_patterns(&["node_modules"]);
        assert!(ignores.should_ignore("src/node_modules"));
        assert!(ignores.should_ignore("../company.reactapp/src/node_modules"));

        let ignores = with_patterns(&["*-test.js"]);
        assert!(ignores.should_ignore("/tmp/a-test.js"));
        assert!(!ignores.should_ignore("/tmp/sourceA.js"));
    }

