    fn expands_trailing_slash_directory_patterns() {
        let ignores = with_patterns(&["sub/dir/"]);
        assert!(ignores.should_ignore("/tmp/sub/dir/file.js"));
        assert!(!ignores.should_ignore("/tmp/sub/file.js"));
    }
