use std::fs::{self, File};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};

static INVOCATIONS: AtomicU32 = AtomicU32::new(0);

/// Writes `contents` to `path` by writing a sibling temporary file and renaming it over the target,
/// keeping the target's mode and owner as `write-file-atomic` does.
pub fn write_file_atomic(path: &str, contents: &str) -> Result<(), std::io::Error> {
    let path = Path::new(path);
    let temp_path = temp_path_for(path);

    let metadata = fs::metadata(path).ok();
    let result = (|| -> Result<(), std::io::Error> {
        let mut file = File::create(&temp_path)?;
        file.write_all(contents.as_bytes())?;
        file.sync_all()?;
        drop(file);
        if let Some(metadata) = &metadata {
            copy_ownership(&temp_path, metadata)?;
            fs::set_permissions(&temp_path, metadata.permissions())?;
        }
        fs::rename(&temp_path, path)
    })();

    if result.is_err() {
        let _ = fs::remove_file(&temp_path);
    }
    result
}

/// `${path}.${hash}` in the original; the name only has to be unique next to the target.
fn temp_path_for(path: &Path) -> PathBuf {
    let invocation = INVOCATIONS.fetch_add(1, Ordering::Relaxed);
    let mut name = path.file_name().unwrap_or_default().to_os_string();
    name.push(format!(".{}{}", std::process::id(), invocation));
    path.with_file_name(name)
}

#[cfg(unix)]
fn copy_ownership(path: &Path, metadata: &fs::Metadata) -> Result<(), std::io::Error> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    use std::os::unix::fs::MetadataExt;

    extern "C" {
        fn chown(path: *const std::ffi::c_char, uid: u32, gid: u32) -> std::ffi::c_int;
    }

    let c_path = CString::new(path.as_os_str().as_bytes())?;
    // SAFETY: `c_path` is a valid NUL-terminated path for the duration of the call. A failure is
    // ignored, matching `write-file-atomic`, which tolerates a missing privilege to chown.
    unsafe { chown(c_path.as_ptr(), metadata.uid(), metadata.gid()) };
    Ok(())
}

#[cfg(not(unix))]
fn copy_ownership(_path: &Path, _metadata: &fs::Metadata) -> Result<(), std::io::Error> {
    Ok(())
}
